		struct NativeCullJobDescriptor
		{
			alignas(8) std::array<std::byte,
				HandMirrorUnifiedCullRuntimePolicy::kVRDescriptorSize> storage{};

			[[nodiscard]] static const NativeCullJobDescriptorLayout& Layout() noexcept
			{
				static const NativeCullJobDescriptorLayout layout = ExactVRRuntime() ?
					NativeCullJobDescriptorLayout::VR() :
					NativeCullJobDescriptorLayout::Flat();
				return layout;
			}

			template <class T>
			[[nodiscard]] T& Field(const std::ptrdiff_t a_offset) noexcept
			{
				return *reinterpret_cast<T*>(storage.data() + a_offset);
			}

			[[nodiscard]] RE::BSShaderAccumulator*& ShaderAccumulator() noexcept
			{
				return Field<RE::BSShaderAccumulator*>(Layout().shaderAccumulator);
			}
			[[nodiscard]] RE::NiCamera*& Camera() noexcept
			{
				return Field<RE::NiCamera*>(Layout().camera);
			}
			[[nodiscard]] void*& CompoundFrustum() noexcept
			{
				return Field<void*>(Layout().compoundFrustum);
			}
			[[nodiscard]] RE::NiFrustum*& Frustum() noexcept
			{
				return Field<RE::NiFrustum*>(Layout().frustum);
			}
			[[nodiscard]] void*& PortalGraphEntry() noexcept
			{
				return Field<void*>(Layout().portalGraphEntry);
			}
			[[nodiscard]] RE::NiFrustumPlanes*& CustomCullPlanes() noexcept
			{
				return Field<RE::NiFrustumPlanes*>(Layout().customCullPlanes);
			}
			[[nodiscard]] RE::NiAVObject*& Scene() noexcept
			{
				return Field<RE::NiAVObject*>(Layout().scene);
			}
			[[nodiscard]] void*& CullingObjects() noexcept
			{
				return Field<void*>(Layout().cullingObjects);
			}
			[[nodiscard]] std::uint32_t& CullMode() noexcept
			{
				return Field<std::uint32_t>(Layout().cullMode);
			}
			[[nodiscard]] bool& IgnorePreprocess() noexcept
			{
				return Field<bool>(Layout().ignorePreprocess);
			}
			[[nodiscard]] bool& DoCustomCullPlanes() noexcept
			{
				return Field<bool>(Layout().doCustomCullPlanes);
			}
			[[nodiscard]] bool& CameraRelatedUpdates() noexcept
			{
				return Field<bool>(Layout().cameraRelatedUpdates);
			}
			// Flat +0x61 / VR +0x71; the byte the borrowed scene lists carry.
			[[nodiscard]] bool& Unk61() noexcept
			{
				return Field<bool>(Layout().unk61);
			}
		};
		static_assert(sizeof(NativeCullJobDescriptor) ==
			HandMirrorUnifiedCullRuntimePolicy::kVRDescriptorSize);
		static_assert(alignof(NativeCullJobDescriptor) == 8);
		static_assert(std::is_trivially_destructible_v<NativeCullJobDescriptor>);

		using NativeCullFromDescriptor = void(NativeCullJobDescriptor*, int, int);

		enum class PrimaryCullRoot : std::uint8_t
		{
			kWorldRoot,
			kRetainedPlayerRoot
		};

		// Which capture a native call belongs to (defined with the private-pass state).
		MirrorNativeCpuTiming::Kind NativeTimingKind() noexcept;

		/**
		 * Skyrim's exterior reflection path temporarily forces the sky root through
		 * culling. Keep that mutation narrower than one root cull and restore only
		 * the exact bit we borrowed. This helper owns no unwind-requiring object, so
		 * its __finally executes before a native fault reaches the existing outer
		 * private-pass SEH cleanup.
		 */
		__declspec(noinline) void CullSkyRootWithAlwaysDrawSEH(
			NativeCullJobDescriptor* a_descriptor,
			RE::NiAVObject* a_skyRoot,
			std::uintptr_t a_cullAddress) noexcept
		{
			if (!a_descriptor || !a_skyRoot || !a_cullAddress)
				return;

			bool priorAlwaysDraw = false;
			bool leaseArmed = false;
			__try {
				auto& flags = a_skyRoot->GetFlags();
				priorAlwaysDraw = flags.any(RE::NiAVObject::Flag::kAlwaysDraw);
				leaseArmed = true;
				flags.set(RE::NiAVObject::Flag::kAlwaysDraw);
				a_descriptor->Scene() = a_skyRoot;
				MirrorNativeCpuTiming::Call(NativeTimingKind(), false,
					reinterpret_cast<NativeCullFromDescriptor*>(a_cullAddress), a_descriptor, 0, 0);
			} __finally {
				if (leaseArmed) {
					a_skyRoot->GetFlags().set(
						priorAlwaysDraw, RE::NiAVObject::Flag::kAlwaysDraw);
				}
			}
		}
		static_assert(NativeCullJobDescriptorLayout::Flat().scene == 0x40);
		static_assert(NativeCullJobDescriptorLayout::Flat().cameraRelatedUpdates == 0x60);
		static_assert(NativeCullJobDescriptorLayout::VR().scene == 0x48);
		static_assert(NativeCullJobDescriptorLayout::VR().cameraRelatedUpdates == 0x70);

		/**
		 * Capture-phase heartbeat.
		 *
		 * The 2026-08-07 GPU livelock localized to NOTHING: the last log line is
		 * emitted before the pass begins, so a hang anywhere inside it looked
		 * identical. These are plain volatile stores of a small enum - no engine
		 * state, no allocation, no logging - so a live dump or the next periodic
		 * snapshot names the exact phase the pass was in when it stopped.
		 */
		enum class CapturePhase : std::uint8_t
		{
			kIdle,
			kTargetBegin,
			kOverrideArm,
			kPreDrainInventory,
			kStartAccumulating,
			kCullWorld,
			kCullPlayerRoot,
			kCullExteriorRoots,
			kCullPoseRestore,
			kFadeReapply,
			kCullModeProgram,
			kDispatch,
			kCullModeRestore,
			kPostDrainInventory,
			kGroupClear,
			kExactMirrorPrimaryBegin,
			kExactMirrorPrimaryDispatch,
			kExactMirrorPrimaryReturn,
			kCleanup,
			kDone
		};

		[[nodiscard]] constexpr const char* CapturePhaseName(CapturePhase a_phase) noexcept
		{
			switch (a_phase) {
			case CapturePhase::kIdle: return "idle";
			case CapturePhase::kTargetBegin: return "target-begin";
			case CapturePhase::kOverrideArm: return "override-arm";
			case CapturePhase::kPreDrainInventory: return "pre-drain-inventory";
			case CapturePhase::kStartAccumulating: return "start-accumulating";
			case CapturePhase::kCullWorld: return "cull-world";
			case CapturePhase::kCullPlayerRoot: return "cull-player-root";
			case CapturePhase::kCullExteriorRoots: return "cull-exterior-roots";
			case CapturePhase::kCullPoseRestore: return "cull-pose-restore";
			case CapturePhase::kFadeReapply: return "fade-reapply";
			case CapturePhase::kCullModeProgram: return "cull-mode-program";
			case CapturePhase::kDispatch: return "DISPATCH";
			case CapturePhase::kCullModeRestore: return "cull-mode-restore";
			case CapturePhase::kPostDrainInventory: return "post-drain-inventory";
			case CapturePhase::kGroupClear: return "group-clear";
			case CapturePhase::kExactMirrorPrimaryBegin:
				return "exact-mirror-primary-begin";
			case CapturePhase::kExactMirrorPrimaryDispatch:
				return "exact-mirror-primary-DISPATCH";
			case CapturePhase::kExactMirrorPrimaryReturn:
				return "exact-mirror-primary-return";
			case CapturePhase::kCleanup: return "cleanup";
			case CapturePhase::kDone: return "done";
			default: return "unknown";
			}
		}

		// Deliberately volatile, not atomic: single writer (the render thread),
		// read only by diagnostics and post-mortem tooling. The volatile stops the
		// optimizer eliding stores that no C++ reader consumes.
		volatile CapturePhase g_capturePhase = CapturePhase::kIdle;
		volatile std::uint64_t g_capturePhaseSequence = 0;
		volatile CapturePhase g_deepestPhase = CapturePhase::kIdle;

		// The phase heartbeat is only visible through periodic diagnostics, which
		// is useless for a HANG: the periodic tick never runs again, so the log's
		// last line is whatever happened to be written before the freeze rather
		// than the phase we died in. Tracing the first few captures to the log
		// costs a handful of lines and names the exact phase. Default-off; arm
		// with Data\RealisticReflections_M3PhaseTrace.enable.
		constexpr std::wstring_view kPhaseTraceMarker =
			L"RealisticReflections_M3PhaseTrace.enable";
		std::atomic_bool g_phaseTraceEnabled{ false };
		constexpr std::wstring_view kMirrorOwnerExclusionMarker =
			L"RealisticReflections_M3MirrorOwnerExclusion.enable";
		std::atomic_bool g_mirrorOwnerExclusionEnabled{ false };
		std::atomic<std::uint32_t> g_phaseTraceCaptures{ 0 };
		constexpr std::uint32_t kPhaseTraceCaptureLimit = 3;

		inline void MarkPhase(CapturePhase a_phase) noexcept
		{
			g_capturePhase = a_phase;
			++g_capturePhaseSequence;
			if (static_cast<std::uint8_t>(a_phase) >
				static_cast<std::uint8_t>(g_deepestPhase)) {
				g_deepestPhase = a_phase;
			}
			if (!g_phaseTraceEnabled.load(std::memory_order_relaxed))
				return;
			// Count captures by their kIdle -> first-phase edge so the limit is in
			// captures, not phases.
			if (a_phase == CapturePhase::kTargetBegin)
				g_phaseTraceCaptures.fetch_add(1, std::memory_order_relaxed);
			if (g_phaseTraceCaptures.load(std::memory_order_relaxed) >
				kPhaseTraceCaptureLimit)
				return;
			try {
				logger::info(
					"[RR][M3][phase] {} (seq={})",
					CapturePhaseName(a_phase),
					static_cast<std::uint64_t>(g_capturePhaseSequence));
				// A hang means the process stops before the sink flushes on its own
				// schedule, so the line we most need is the one most likely to be
				// lost. Flush every traced phase.
				if (auto* const log = spdlog::default_logger_raw())
					log->flush();
			} catch (...) {
			}
		}

