		struct NativeViewConstruction
		{
			std::uintptr_t cameraConstructor;
			std::uintptr_t accumulatorConstructor;
			std::size_t cameraBytes;
			std::size_t accumulatorBytes;
			bool monoVR;
		};

		[[nodiscard]] NativeViewConstruction NativeViewConstructionForRuntime() noexcept
		{
			const auto version = REL::Module::get().version();
			if (version == REL::Version{ 1, 5, 97, 0 })
				return { 0xC65090, 0x12C9C90, 0x188, 0x180, false };
			if (version == REL::Version{ 1, 6, 1170, 0 })
				return { 0xD2AFA0, 0x14B1CF0, 0x188, 0x180, false };
			if (version == REL::Version{ 1, 7, 104, 0 })
				return { 0xEEF9A0, 0x151DEA0, 0x188, 0x180, false };
			if (version == REL::Version{ 1, 4, 15, 0 })
				return { 0xCAA7F0, 0x1308080, 0x208, 0x1B0, true };
			return {};
		}

		class NativeViewOwner
		{
		public:
			NativeViewOwner() = default;
			NativeViewOwner(const NativeViewOwner&) = delete;
			NativeViewOwner& operator=(const NativeViewOwner&) = delete;

			[[nodiscard]] bool EnsureCreated() noexcept
			{
				if (camera && accumulator) return true;
				const auto recipe = NativeViewConstructionForRuntime();
				if (!recipe.cameraConstructor || !recipe.accumulatorConstructor) return false;
				void* cameraAllocation = RE::malloc(recipe.cameraBytes);
				if (!cameraAllocation) return false;
				RE::NiCamera* initializedCamera = nullptr;
				__try {
					if (recipe.monoVR) {
						using Constructor = RE::NiCamera*(void*, std::uint32_t);
						REL::Relocation<Constructor> construct{ REL::Offset(recipe.cameraConstructor) };
						initializedCamera = construct(cameraAllocation, 1);
					} else {
						using Constructor = RE::NiCamera*(void*);
						REL::Relocation<Constructor> construct{ REL::Offset(recipe.cameraConstructor) };
						initializedCamera = construct(cameraAllocation);
					}
					if (initializedCamera != cameraAllocation) return false;
					initializedCamera->IncRefCount();
					camera = initializedCamera;
					auto& frustum = camera->GetRuntimeData2().viewFrustum;
					frustum.fLeft = -1.0F; frustum.fRight = 1.0F;
					frustum.fTop = 1.0F; frustum.fBottom = -1.0F;
					frustum.fNear = 1.0F; frustum.fFar = 2048.0F;
					frustum.bOrtho = false;
					if (recipe.monoVR) {
						auto& runtime = camera->GetVRRuntimeData();
						if (!runtime.viewFrustumBuffer) { Reset(); return false; }
						*runtime.viewFrustumBuffer = frustum;
					}
					void* accumulatorAllocation = RE::malloc(recipe.accumulatorBytes);
					if (!accumulatorAllocation) { Reset(); return false; }
					using Constructor = RE::BSShaderAccumulator*(void*, std::uint32_t);
					REL::Relocation<Constructor> construct{ REL::Offset(recipe.accumulatorConstructor) };
					auto* initializedAccumulator = construct(accumulatorAllocation, 99);
					if (initializedAccumulator != accumulatorAllocation) { Reset(); return false; }
					initializedAccumulator->IncRefCount();
					accumulator = initializedAccumulator;
					return true;
				} __except (RecordException(GetExceptionCode())) {
					// An incomplete native constructor may own suballocations. Do not
					// guess its destruction phase; the fault latch prevents reuse.
					camera = nullptr;
					accumulator = nullptr;
					return false;
				}
			}

			void Reset() noexcept
			{
				auto* oldAccumulator = accumulator;
				auto* oldCamera = camera;
				accumulator = nullptr;
				camera = nullptr;
				Release(oldAccumulator);
				Release(oldCamera);
			}

			[[nodiscard]] RE::NiCamera* Camera() const noexcept { return camera; }
			[[nodiscard]] RE::BSShaderAccumulator* Accumulator() const noexcept { return accumulator; }

		private:
			static int RecordException(unsigned long code) noexcept;
			static void Release(RE::NiRefObject* object) noexcept
			{
				if (!object) return;
				__try { object->DecRefCount(); }
				__except (RecordException(GetExceptionCode())) {}
			}
			RE::NiCamera* camera{ nullptr };
			RE::BSShaderAccumulator* accumulator{ nullptr };
		};

		Counters g_counters{};
		NativeViewOwner g_owner{};  // Intentionally retained while render hooks are live.
		// The supplemental actor pass must never register passes in the borrowed-world
		// accumulator. This second native owner supplies a disjoint accumulator while
		// the primary mirror target/depth and reflected camera remain scoped by the
		// outer private pass.
		NativeViewOwner g_supplementalActorOwner{};
		// Depth pre-pass accumulator (owner 2026-09-14: reflected shadows under
		// Community Shaders). The engine renders its own Z pre-pass through a second
		// accumulator in render mode 12, whose registration table entry builds depth
		// passes instead of lighting passes (SE 1.5.97: 0x1431D1B40[12] =
		// 0x1412CA9C0, finisher 0x1431D1C40[12] = 0x1412CC3C0). A private capture
		// does the same so its shadow mask can be evaluated before any shading.
		NativeViewOwner g_depthPrePassOwner{};
		inline constexpr std::uint32_t kDepthPrePassRenderMode = 12;
		thread_local std::uint64_t g_depthPrePassSequence{ 0 };
		// Where a pre-pass stopped. Run 25 produced no mask at all and the
		// counters could not say whether the target, the shadow setting, the
		// roster cull or the map was the reason.
		enum class DepthPrePassStage : std::uint32_t
		{
			kNotRun = 0,
			kRouteClosed = 1,
			kTargetUnavailable = 2,
			kShadowsDisabled = 3,
			kOwnerUnavailable = 4,
			kLeftoverPasses = 5,
			kSupplementalCull = 6,
			kDepthTargetMissing = 7,
			kRendered = 8,
			kMaskRejected = 9,
			kMasked = 10,
			// No private sun maps for this source frame (every interior): the mask
			// would reject anyway, so the depth-only render is not run at all.
			kNoSunMaps = 11
		};
		struct DepthPrePassOutcome
		{
			// A render happened, so this cycle patched a camera upload that can be
			// proven and handed to the colour cycles. Without one nothing was
			// touched and the capture must continue exactly as it did before.
			bool rendered{ false };
			bool masked{ false };
			DepthPrePassStage stage{ DepthPrePassStage::kNotRun };
		};
		NativeViewOwner g_privateShadowOwner{};
		RenderTarget g_privateShadowTarget{};
		NativeViewOwner g_privateDetailShadowOwner{};
		RenderTarget g_privateDetailShadowTarget{};
		// A published SRV retains the resource object, not frozen contents. The
		// default-off continuity route ping-pongs mirror capture/published targets so
		// a failed replacement cannot overwrite the last completed frame. Flat metal
		// and flat glass each keep their legacy singleton unless their own
		// multi-surface marker lazily warms a disjoint 4-retained+1-staging pool.
		RenderTarget* g_mirrorTarget = nullptr;
		RenderTarget* g_mirrorPublishedTarget = nullptr;
		std::vector<RenderTarget*> g_mirrorRetainedTargets{};
		std::vector<std::uint64_t> g_mirrorRetainedGenerations{};
		MultiMirrorPolicy::Scheduler g_multiMirrorScheduler{};
		std::size_t g_activeMirrorSlot{ 0 };
		std::atomic_bool g_vrCameraLayoutFixEnabled{ false };
		std::uint64_t g_mirrorTargetGeneration{ 0 };
		std::uint64_t g_mirrorPublishedTargetGeneration{ 0 };
		// Domain-separated from low hand-role generations and the high-bit main
		// target pair generation maintained by MirrorPaneDelivery.
		std::uint64_t g_mirrorTargetGenerationCursor{
			UINT64_C(0x4000000000000000) };
		
		
		
		
		
		
		
		
