		[[nodiscard]] bool SameCapturePlane(
			const PlanarMirrorMath::Plane& a_left,
			const PlanarMirrorMath::Plane& a_right) noexcept;

		[[nodiscard]] bool MirrorPublicationRoleIsDisjoint(
			const MirrorFramePublication::Snapshot& a_snapshot) noexcept
		{
			if (MirrorFleetPolicy::enabled.load(std::memory_order_relaxed) &&
				MirrorFramePublication::MultiMirrorEnabled() && !a_snapshot.depthSRV) {
				return g_mirrorPublishedTarget && g_mirrorPublishedTarget->Ready() &&
					!g_mirrorPublishedTarget->Bound() && a_snapshot.colorSRV &&
					a_snapshot.colorSRV.Get() == g_mirrorPublishedTarget->ColorSRV() &&
					(!g_mirrorTarget || (g_mirrorTarget != g_mirrorPublishedTarget && !g_mirrorTarget->Bound() &&
						g_mirrorTarget->LastRestoreStatus() != RenderTarget::RestoreStatus::kFault &&
						((!g_mirrorTarget->ColorResourceIdentity() && !g_mirrorTarget->DepthResourceIdentity()) ||
							MirrorFramePublication::CaptureResourcesDisjoint(g_mirrorTarget->ColorResourceIdentity(),
								g_mirrorTarget->DepthResourceIdentity()))));
			}
			if (!g_mirrorPublishedTarget || !g_mirrorPublishedTarget->Ready() ||
				g_mirrorPublishedTarget->Bound() || !a_snapshot.colorSRV ||
				!a_snapshot.depthSRV ||
				a_snapshot.colorSRV.Get() != g_mirrorPublishedTarget->ColorSRV() ||
				a_snapshot.depthSRV.Get() != g_mirrorPublishedTarget->DepthSRV()) {
				return false;
			}
			if (!g_mirrorTarget)
				return true;
			if (g_mirrorTarget == g_mirrorPublishedTarget || g_mirrorTarget->Bound())
				return false;

			const auto* const publishedColor =
				g_mirrorPublishedTarget->ColorResourceIdentity();
			const auto* const publishedDepth =
				g_mirrorPublishedTarget->DepthResourceIdentity();
			const auto* const captureColor = g_mirrorTarget->ColorResourceIdentity();
			const auto* const captureDepth = g_mirrorTarget->DepthResourceIdentity();
			if (!captureColor || !captureDepth || !publishedColor || !publishedDepth)
				return false;
			return captureColor != publishedColor &&
				captureColor != publishedDepth &&
				captureDepth != publishedColor &&
				captureDepth != publishedDepth &&
				captureColor != captureDepth &&
				publishedColor != publishedDepth;
		}

		

		[[nodiscard]] bool PlanarPublicationCanSurviveUnstartedCapture(
			RenderTarget* a_captureTarget,
			RenderTarget* a_publishedTarget,
			ID3D11ShaderResourceView* a_publishedColor,
			ID3D11ShaderResourceView* a_publishedDepth = nullptr) noexcept
		{
			if (!a_publishedTarget || !a_publishedTarget->Ready() ||
				a_publishedTarget->Bound() || !a_publishedColor ||
				a_publishedColor != a_publishedTarget->ColorSRV() ||
				(a_publishedDepth &&
				 a_publishedDepth != a_publishedTarget->DepthSRV())) {
				return false;
			}
			const auto* const publishedColor =
				a_publishedTarget->ColorResourceIdentity();
			const auto* const publishedDepth =
				a_publishedTarget->DepthResourceIdentity();
			if (!publishedColor || !publishedDepth ||
				publishedColor == publishedDepth) {
				return false;
			}
			if (!a_captureTarget)
				return true;
			if (a_captureTarget == a_publishedTarget || a_captureTarget->Bound())
				return false;

			// EnsureRenderObjects failed before Begin, so absent partial identities
			// have never been writable.  Any identity that does exist must be
			// cross-role-disjoint from the retained publication.
			const auto* const captureColor =
				a_captureTarget->ColorResourceIdentity();
			const auto* const captureDepth =
				a_captureTarget->DepthResourceIdentity();
			return (!captureColor ||
				(captureColor != publishedColor &&
				 captureColor != publishedDepth)) &&
				(!captureDepth ||
				 (captureDepth != publishedColor &&
				  captureDepth != publishedDepth)) &&
				(!captureColor || !captureDepth || captureColor != captureDepth);
		}

