		template <std::size_t N>
		[[nodiscard]] RenderTarget* FindPublishedPlanarPoolTarget(
			const std::array<RenderTarget*, N>& a_targets,
			ID3D11ShaderResourceView* a_color,
			ID3D11ShaderResourceView* a_depth) noexcept
		{
			if (!a_color || !a_depth)
				return nullptr;
			for (auto* target : a_targets) {
				if (target && target->ColorSRV() == a_color &&
					target->DepthSRV() == a_depth) {
					return target;
				}
			}
			return nullptr;
		}

