		struct MultiMirrorFrameBatch
		{
			MultiMirrorPolicy::FramePlan plan{};
			MirrorFleetPolicy::FrameQuality quality{};
			HandMirrorReflectionRuntime::FenceSelection handSelection{};
			std::vector<PlanarCaptureOpportunityPolicy::Coordinator> coordinators{};
			std::vector<DeferredExactMirrorCapture> mirrors{};
			std::vector<DeferredExactHandCapture> hands{};
			std::vector<const char*> failures{};
			std::uint64_t source{};
			std::size_t activeIndex{ MultiMirrorPolicy::kNone };
			bool preparing{};
			bool prepared{};
			bool consumed{};
			bool EnsureEntries(std::size_t count) noexcept
			{
				try {
					if (coordinators.size() < count) coordinators.resize(count);
					if (mirrors.size() < count) mirrors.resize(count);
					if (hands.size() < count) hands.resize(count);
					if (failures.size() < count) failures.resize(count, "not-prepared");
					return true;
				} catch (...) {
					return false;
				}
			}
			bool Begin(std::uint64_t nextSource) noexcept
			{
				for (auto& entry : coordinators) entry = {};
				for (auto& entry : mirrors) entry = {};
				for (auto& entry : hands) entry = {};
				plan.captures.clear();
				plan.source = plan.count = 0;
				// Keep the last complete quality snapshot if candidate discovery fails.
				handSelection = {};
				source = nextSource;
				activeIndex = MultiMirrorPolicy::kNone;
				preparing = true;
				prepared = consumed = false;
				return EnsureEntries(1);
			}
		};
