		[[nodiscard]] std::uint64_t PackFloatPair(
			const float low,
			const float high) noexcept
		{
			return static_cast<std::uint64_t>(std::bit_cast<std::uint32_t>(low)) |
				(static_cast<std::uint64_t>(std::bit_cast<std::uint32_t>(high)) << 32);
		}

		

		void StoreMaximumNonnegativeFloat(
			std::atomic<std::uint32_t>& destination,
			const float value) noexcept
		{
			if (!std::isfinite(value) || value <= 0.0F)
				return;
			const auto desired = std::bit_cast<std::uint32_t>(value);
			auto current = destination.load(std::memory_order_relaxed);
			while (current < desired &&
				!destination.compare_exchange_weak(
					current, desired, std::memory_order_relaxed,
					std::memory_order_relaxed)) {
			}
		}

		[[nodiscard]] HandMirrorPortraitClipPolicy::PhysicalPaneNearSelection
		ObserveHandPortraitPhysicalPaneAxialDepth(
			const HandMirrorContentRuntimePolicy::PanePoseGeometry& pane,
			const MirrorCameraOverride::CameraPose& reflectedPose,
			const float virtualNearDepth,
			const HandPortraitRetainedBounds& retainedBounds,
			const float farPlane) noexcept
		{
			g_handPortraitPhysicalClipSamples.fetch_add(1, std::memory_order_relaxed);
			const auto dotForward = [&](const auto& value) noexcept {
				return value.x * reflectedPose.forward.x +
					value.y * reflectedPose.forward.y +
					value.z * reflectedPose.forward.z;
			};
			const HandMirrorContentRuntimePolicy::Float3 centerOffset{
				pane.center.x - reflectedPose.origin.x,
				pane.center.y - reflectedPose.origin.y,
				pane.center.z - reflectedPose.origin.z
			};
			if (!retainedBounds.valid ||
				!retainedBounds.tupleRevalidatedAfterTraversal ||
				retainedBounds.actorRenderRootIdentity == 0 ||
				retainedBounds.faceNodeIdentity == 0 ||
				retainedBounds.selectedGraphicsFrame == 0) {
				g_handPortraitPhysicalClipBoundsUnavailable.fetch_add(
					1, std::memory_order_relaxed);
				return {};
			}
			const auto retainedAxialDepth =
				HandMirrorPortraitClipPolicy::
					ComputeRetainedBoundsNearestAxialDepth(
						retainedBounds.geometry,
						reflectedPose.origin.x, reflectedPose.origin.y,
						reflectedPose.origin.z, reflectedPose.forward.x,
						reflectedPose.forward.y, reflectedPose.forward.z);
			if (!retainedAxialDepth.valid) {
				g_handPortraitPhysicalClipBoundsUnavailable.fetch_add(
					1, std::memory_order_relaxed);
				return {};
			}
			const float retainedBoundsNearestDepth = retainedAxialDepth.nearestDepth;
			const auto observation =
				HandMirrorPortraitClipPolicy::ObservePhysicalPaneAxialDepth({
					.centerDepth = dotForward(centerOffset),
					.normalForwardDot = dotForward(pane.normal),
					.tangentForwardDot = dotForward(pane.tangent),
					.bitangentForwardDot = dotForward(pane.bitangent),
					.halfWidth = pane.halfWidth,
					.halfHeight = pane.halfHeight,
					.frontClearance = pane.frontClearance,
					.backClearance = pane.backClearance,
					.virtualNearDepth = virtualNearDepth,
					.retainedAnchorDepth = retainedBoundsNearestDepth
				});
			if (!observation.valid) {
				g_handPortraitPhysicalClipInvalidSamples.fetch_add(
					1, std::memory_order_relaxed);
				return {};
			}
			g_handPortraitPhysicalClipLastNearDepths.store(
				PackFloatPair(
					virtualNearDepth, observation.physicalDeepestDepth),
				std::memory_order_relaxed);
			g_handPortraitPhysicalClipLastMargins.store(
				PackFloatPair(
					observation.physicalMinusVirtual,
					observation.retainedAnchorClearance),
				std::memory_order_relaxed);
			if (observation.physicalWouldAdvanceNear) {
				g_handPortraitPhysicalClipWouldAdvance.fetch_add(
					1, std::memory_order_relaxed);
				StoreMaximumNonnegativeFloat(
					g_handPortraitPhysicalClipMaximumLeadBits,
					observation.physicalMinusVirtual);
			}
			if (observation.physicalAdvanceWouldViolateAnchorMargin) {
				g_handPortraitPhysicalClipAnchorUnsafe.fetch_add(
					1, std::memory_order_relaxed);
				StoreMaximumNonnegativeFloat(
					g_handPortraitPhysicalClipMaximumShortfallBits,
					HandMirrorPortraitClipPolicy::
						kMinimumRetainedAnchorDepthMargin -
						observation.retainedAnchorClearance);
			}
			const auto selection =
				HandMirrorPortraitClipPolicy::SelectPhysicalPaneNearDepth(
					virtualNearDepth, observation.physicalDeepestDepth,
					retainedBoundsNearestDepth, farPlane);
			if (selection.valid && selection.applied) {
				g_handPortraitPhysicalClipApplied.fetch_add(
					1, std::memory_order_relaxed);
				if (selection.clampedToRetainedBounds) {
					g_handPortraitPhysicalClipClamped.fetch_add(
						1, std::memory_order_relaxed);
				}
			}
			return selection;
		}

		[[nodiscard]] bool BuildHandPortraitPhysicalWorldCullPlane(
			const HandPortraitPhysicalClipEvidence& evidence,
			PlanarMirrorMath::Plane& output) noexcept
		{
			output = {};
			if (!evidence.valid || evidence.selectedGraphicsFrame == 0 ||
				!HandMirrorContentRuntimePolicy::IsSanePoseGeometry(evidence.pane)) {
				return false;
			}
			const auto& pane = evidence.pane;
			const auto halfSpace =
				HandMirrorPortraitClipPlanePolicy::Select({
					.centerX = pane.center.x,
					.centerY = pane.center.y,
					.centerZ = pane.center.z,
					.normalX = pane.normal.x,
					.normalY = pane.normal.y,
					.normalZ = pane.normal.z,
					.frontClearance = pane.frontClearance,
					.backClearance = pane.backClearance,
					.keepPointX = evidence.worldKeepPoint.x,
					.keepPointY = evidence.worldKeepPoint.y,
					.keepPointZ = evidence.worldKeepPoint.z
				}, {evidence.portraitClipNormal.x, evidence.portraitClipNormal.y,
					evidence.portraitClipNormal.z}, evidence.stableClipNormal);
			if (!halfSpace)
				return false;
			output = {
				.normal = { halfSpace.normalX, halfSpace.normalY, halfSpace.normalZ },
				.distance = halfSpace.distance
			};
			if (HandMirrorSafetySettings::HeadClearance() && !REL::Module::IsVR()) {
				const auto& retained = evidence.retainedBounds;
				if (!retained.valid || !retained.tupleRevalidatedAfterTraversal ||
					!retained.geometry.valid || !retained.actorRenderRootIdentity ||
					retained.selectedGraphicsFrame != evidence.selectedGraphicsFrame)
					return false;
				const auto& b = retained.geometry;
				HandMirrorPhysicalFragmentClipPolicy::PlaneDomainInputs head{
					.normalX=output.normal.x, .normalY=output.normal.y, .normalZ=output.normal.z,
					.distance=output.distance,
					.minimumX=b.minimumX, .minimumY=b.minimumY, .minimumZ=b.minimumZ,
					.maximumX=b.maximumX, .maximumY=b.maximumY, .maximumZ=b.maximumZ};
				if (!HandMirrorPhysicalFragmentClipPolicy::KeepHeadAheadOfPlane(head))
					return false;
				if (head.distance < output.distance)
					g_handHeadPlaneRetreats.fetch_add(1, std::memory_order_relaxed);
				output.distance = head.distance;
			}
			return true;
		}

		[[nodiscard]] bool SameHandPortraitCalibrationOwner(
			const HandMirrorContentRuntimePolicy::HandMirrorOwnerIdentity& left,
			const HandMirrorContentRuntimePolicy::HandMirrorOwnerIdentity& right) noexcept
		{
			using HandMirrorContentRuntimePolicy::IsValidHandMirrorOwnerIdentity;
			return IsValidHandMirrorOwnerIdentity(left) &&
				IsValidHandMirrorOwnerIdentity(right) &&
				left.playerFormID == right.playerFormID &&
				left.playerHandleToken == right.playerHandleToken &&
				left.armorPluginIdentity == right.armorPluginIdentity &&
				left.armorLocalFormID == right.armorLocalFormID &&
				left.armorBase == right.armorBase &&
				left.armorAddonPluginIdentity == right.armorAddonPluginIdentity &&
				left.armorAddonLocalFormID == right.armorAddonLocalFormID &&
				left.armorAddonBase == right.armorAddonBase &&
				left.shieldSlotNumber == right.shieldSlotNumber &&
				left.authoredSurface == right.authoredSurface &&
				left.visibleModelAssetIdentity == right.visibleModelAssetIdentity &&
				left.captureModelAssetIdentity == right.captureModelAssetIdentity &&
				left.perspective == right.perspective;
		}
