		// Hand-only stabilization of vanilla's per-surface illumination. The native
		// selector always runs first, preserving its dead-light scrub and every side
		// effect. A same-source main-view result is then replayed in exact vanilla order
		// with local shadow selection disabled. Mirror-only cache misses acquire the
		// first nonempty exact-private/global cohort immediately; private-camera
		// active-mask churn cannot replace it after that cohort seals. The main view is
		// observed only and every private local remains illumination-only.
		constexpr std::size_t kHandSurfaceLightReplayCapacity = 2048;
		constexpr std::size_t kHandSurfaceLightReplayProbeLimit = 64;
		constexpr std::size_t kHandSurfaceLightMainCacheCapacity = 8192;
		constexpr std::size_t kHandSurfaceLightMainCacheProbeLimit = 64;
		constexpr std::size_t kHandSurfaceLightMaximumOutput = 16;
		constexpr std::size_t kHandSurfaceLightRecentCapacity = 16;
		constexpr std::size_t kHandSurfaceLightRosterCapacity =
			kHandSurfaceLightMaximumOutput + 32;
		constexpr std::uint64_t kHandSurfaceLightWindowFrames = 4;
		constexpr std::uint64_t kHandSurfaceLightColdFrames = 600;
		constexpr std::uint8_t kHandSurfaceLightManagerMissRetirementSources = 4;
		constexpr std::uint64_t kHandSurfaceLightDemandTailSources =
			2 * kHandSurfaceLightWindowFrames;
		static_assert(
			(kHandSurfaceLightReplayCapacity &
				(kHandSurfaceLightReplayCapacity - 1)) == 0);
		static_assert(
			(kHandSurfaceLightMainCacheCapacity &
				(kHandSurfaceLightMainCacheCapacity - 1)) == 0);
		static_assert(std::is_base_of_v<RE::NiRefObject, RE::BSLight>);

		struct HandSurfaceLightToken
		{
			RE::BSLight* light{ nullptr };
			const RE::NiLight* niLight{ nullptr };
			std::uint64_t fingerprint{ 0 };

			[[nodiscard]] bool operator==(
				const HandSurfaceLightToken& other) const noexcept
			{
				return light != nullptr && niLight != nullptr &&
				       light == other.light && niLight == other.niLight &&
				       fingerprint == other.fingerprint;
			}
		};

