		std::uint16_t g_handSurfaceLightMainCacheUsedCount{ 0 };
		std::uint64_t g_handSurfaceLightMainCacheSourceSequence{ 0 };
		std::uint64_t g_handSurfaceLightOwnedSession{ 0 };
		std::atomic<std::uint32_t> g_handSurfaceLightReplayThread{ 0 };
		std::atomic_bool g_handSurfaceLightCohortRequested{ false };
		std::atomic_bool g_handSurfaceLightCohortHookInstalled{ false };
		std::atomic_bool g_handSurfaceLightBuildHookInstalled{ false };
		std::atomic_bool g_handSurfaceLightBuildActive{ false };
		std::atomic_bool g_handSurfaceLightCohortEnabled{ false };
		std::atomic<std::uint64_t> g_handSurfaceLightCohortSession{ 1 };
