		int NativeViewOwner::RecordException(unsigned long a_code) noexcept
		{
			g_lastException.store(a_code, std::memory_order_relaxed);
			LatchFault(__LINE__);
			return EXCEPTION_EXECUTE_HANDLER;
		}

		// Faulting instruction of the last pass exception, as module+offset, with
		// the capture phase current at that moment (VR 2026-09-05 14:57: the
		// first private pass latched with only "SEH=0xC0000005, phase=done").
		std::atomic<std::uintptr_t> g_lastExceptionAddress{ 0 };
		std::atomic<std::uint8_t> g_lastExceptionPhase{ 0 };

		[[nodiscard]] int RecordPassException(unsigned long a_code) noexcept
		{
			g_lastException.store(a_code, std::memory_order_relaxed);
			LatchFault(__LINE__);
			return EXCEPTION_EXECUTE_HANDLER;
		}

		std::atomic<std::uint32_t> g_lastExceptionSite{ 0 };

		[[nodiscard]] int RecordPassException(
			unsigned long a_code, _EXCEPTION_POINTERS* a_pointers,
			const std::uint32_t a_site = 0) noexcept
		{
			g_lastExceptionSite.store(a_site, std::memory_order_relaxed);
			if (a_pointers && a_pointers->ExceptionRecord) {
				g_lastExceptionAddress.store(
					reinterpret_cast<std::uintptr_t>(
						a_pointers->ExceptionRecord->ExceptionAddress),
					std::memory_order_relaxed);
			}
			g_lastExceptionPhase.store(
				static_cast<std::uint8_t>(g_capturePhase), std::memory_order_relaxed);
			return RecordPassException(a_code);
		}

		/** "module+0xOFFSET" for a code address, or the raw address when unknown. */
		[[nodiscard]] std::string DescribeCodeAddress(const std::uintptr_t a_address)
		{
			if (a_address == 0)
				return "none";
			HMODULE module = nullptr;
			if (GetModuleHandleExW(
					GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
						GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
					reinterpret_cast<LPCWSTR>(a_address), &module) &&
				module) {
				wchar_t path[MAX_PATH]{};
				const auto length = GetModuleFileNameW(module, path, MAX_PATH);
				std::wstring name{ path, length };
				const auto slash = name.find_last_of(L"\\/");
				if (slash != std::wstring::npos)
					name = name.substr(slash + 1);
				const auto utf8Length = WideCharToMultiByte(
					CP_UTF8, 0, name.data(), static_cast<int>(name.size()),
					nullptr, 0, nullptr, nullptr);
				std::string moduleName(static_cast<std::size_t>(utf8Length), '\0');
				if (utf8Length != 0)
					WideCharToMultiByte(CP_UTF8, 0, name.data(),
						static_cast<int>(name.size()), moduleName.data(),
						utf8Length, nullptr, nullptr);
				return fmt::format(
					"{}+0x{:X}", moduleName,
					a_address - reinterpret_cast<std::uintptr_t>(module));
			}
			return fmt::format("0x{:X}", a_address);
		}

		[[nodiscard]] bool GenerateColorMipsSEH(
			RenderTarget* a_target,
			ID3D11DeviceContext* a_context) noexcept
		{
			bool generated = false;
			__try {
				generated = a_target && a_context &&
					a_target->GenerateColorMips(a_context);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				generated = false;
			}
			return generated;
		}

		void ReleaseShaderViewSEH(ID3D11ShaderResourceView*& view) noexcept
		{
			if (!view)
				return;
			__try {
				view->Release();
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
			}
			view = nullptr;
		}

		[[nodiscard]] bool RetainHandTargetSRVsSEH(
			RenderTarget* target,
			Microsoft::WRL::ComPtr<ID3D11ShaderResourceView>& colorOutput,
			Microsoft::WRL::ComPtr<ID3D11ShaderResourceView>& depthOutput) noexcept
		{
			auto* oldColor = colorOutput.Detach();
			auto* oldDepth = depthOutput.Detach();
			ReleaseShaderViewSEH(oldDepth);
			ReleaseShaderViewSEH(oldColor);
			ID3D11ShaderResourceView* color = nullptr;
			ID3D11ShaderResourceView* depth = nullptr;
			bool colorRetained = false;
			bool depthRetained = false;
			bool valid = false;
			__try {
				if (target && !target->Bound() && target->Ready() &&
					target->Width() != 0 && target->Height() != 0) {
					color = target->ColorSRV();
					depth = target->DepthSRV();
					if (color && depth) {
						color->AddRef();
						colorRetained = true;
						depth->AddRef();
						depthRetained = true;
						valid = true;
					}
				}
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				valid = false;
			}
			if (!valid) {
				if (depthRetained)
					ReleaseShaderViewSEH(depth);
				if (colorRetained)
					ReleaseShaderViewSEH(color);
				return false;
			}
			colorOutput.Attach(color);
			depthOutput.Attach(depth);
			return true;
		}

		/**
		 * The native private-pass boundary is the only SEH site whose first fault
		 * needs instruction-level attribution. Keep this filter allocation-free and
		 * silent: cleanup still has to unwind the private camera/target leases before
		 * diagnostics are safe. A separate publication bit prevents readers from
		 * observing the winning writer's partially populated snapshot.
		 */
		void CaptureNativeFaultStackCandidates(
			const CONTEXT* context,
			NativePassFaultSnapshot& snapshot) noexcept
		{
#if defined(_M_X64)
			if (!context || context->Rsp == 0)
				return;
			const auto stackAddress = static_cast<std::uintptr_t>(context->Rsp);
			MEMORY_BASIC_INFORMATION memory{};
			if (VirtualQuery(
					reinterpret_cast<const void*>(stackAddress), &memory,
					sizeof(memory)) != sizeof(memory) ||
				memory.State != MEM_COMMIT || (memory.Protect & PAGE_GUARD) != 0 ||
				(memory.Protect & 0xFFu) == PAGE_NOACCESS) {
				return;
			}
			const auto regionBase = reinterpret_cast<std::uintptr_t>(memory.BaseAddress);
			if (stackAddress < regionBase ||
				memory.RegionSize > std::numeric_limits<std::uintptr_t>::max() - regionBase) {
				return;
			}
			const auto regionEnd = regionBase + memory.RegionSize;
			if (stackAddress >= regionEnd)
				return;
			const auto availableWords = (regionEnd - stackAddress) / sizeof(std::uint64_t);
			const auto wordCount = std::min<std::size_t>(
				kNativeDepthFaultStackCandidateCount, availableWords);
			if (wordCount == 0)
				return;
			std::memcpy(
				snapshot.stackCandidates.data(),
				reinterpret_cast<const void*>(stackAddress),
				wordCount * sizeof(std::uint64_t));
			snapshot.stackCandidateCount = static_cast<std::uint32_t>(wordCount);
#else
			(void)context;
			(void)snapshot;
#endif
		}

		[[nodiscard]] int RecordNativePassException(
			unsigned long a_code,
			EXCEPTION_POINTERS* a_exceptionPointers) noexcept
		{
			g_lastException.store(a_code, std::memory_order_relaxed);
			LatchFault(__LINE__);

			bool expected = false;
			if (g_nativePassFaultClaimed.compare_exchange_strong(
					expected, true, std::memory_order_acq_rel,
					std::memory_order_relaxed)) {
				NativePassFaultSnapshot snapshot{};
				snapshot.code = static_cast<std::uint32_t>(a_code);
				snapshot.capturePhase = g_capturePhase;
				snapshot.capturePhaseSequence = g_capturePhaseSequence;

				const EXCEPTION_RECORD* const record =
					a_exceptionPointers ? a_exceptionPointers->ExceptionRecord : nullptr;
				if (record) {
					snapshot.code = static_cast<std::uint32_t>(record->ExceptionCode);
					snapshot.flags = static_cast<std::uint32_t>(record->ExceptionFlags);
					snapshot.exceptionAddress = reinterpret_cast<std::uintptr_t>(
						record->ExceptionAddress);
					if ((record->ExceptionCode == EXCEPTION_ACCESS_VIOLATION ||
							record->ExceptionCode == EXCEPTION_IN_PAGE_ERROR) &&
						record->NumberParameters >= 2) {
						snapshot.accessViolationParametersPresent = 1;
						snapshot.accessViolationOperation = record->ExceptionInformation[0];
						snapshot.accessViolationAddress = record->ExceptionInformation[1];
					}
				}

				const CONTEXT* const context =
					a_exceptionPointers ? a_exceptionPointers->ContextRecord : nullptr;
				if (context) {
#if defined(_M_X64)
					snapshot.rip = context->Rip;
					snapshot.rsp = context->Rsp;
					snapshot.rbp = context->Rbp;
					if (g_nativeDepthFaultProbeEnabled.load(std::memory_order_relaxed)) {
						snapshot.depthProbeEnabled = 1;
						snapshot.rax = context->Rax;
						snapshot.rcx = context->Rcx;
						snapshot.rdx = context->Rdx;
						snapshot.r8 = context->R8;
						snapshot.r9 = context->R9;
						snapshot.depthProbe = g_nativeDepthFaultProbeCapture;
						CaptureNativeFaultStackCandidates(context, snapshot);
					}
#endif
				}

				if (snapshot.exceptionAddress != 0) {
					MEMORY_BASIC_INFORMATION memory{};
					if (VirtualQuery(
							reinterpret_cast<const void*>(snapshot.exceptionAddress),
							&memory, sizeof(memory)) == sizeof(memory)) {
						snapshot.virtualQuerySucceeded = 1;
						snapshot.allocationBase = reinterpret_cast<std::uintptr_t>(
							memory.AllocationBase);
						snapshot.allocationType = memory.Type;
						if ((memory.Type & MEM_IMAGE) != 0 &&
							snapshot.exceptionAddress >= snapshot.allocationBase) {
							snapshot.imageRva =
								snapshot.exceptionAddress - snapshot.allocationBase;
						}
					}
				}

				g_nativePassFaultSnapshot = snapshot;
				g_nativePassFaultPublished.store(true, std::memory_order_release);
			}
			return EXCEPTION_EXECUTE_HANDLER;
		}

		void LogNativePassFaultDiagnosticOnce()
		{
			if (!g_nativePassFaultPublished.load(std::memory_order_acquire))
				return;
			bool expected = false;
			if (!g_nativePassFaultReported.compare_exchange_strong(
					expected, true, std::memory_order_acq_rel,
					std::memory_order_relaxed)) {
				return;
			}

			const NativePassFaultSnapshot snapshot = g_nativePassFaultSnapshot;
			std::array<wchar_t, MAX_PATH> wideModulePath{};
			std::array<char, MAX_PATH * 3> utf8ModulePath{};
			const char* modulePath = "<unresolved>";
			if (snapshot.allocationBase != 0 &&
				(snapshot.allocationType & MEM_IMAGE) != 0) {
				const DWORD wideLength = GetModuleFileNameW(
					reinterpret_cast<HMODULE>(snapshot.allocationBase),
					wideModulePath.data(), static_cast<DWORD>(wideModulePath.size()));
				if (wideLength != 0 && wideLength < wideModulePath.size()) {
					const int utf8Length = WideCharToMultiByte(
						CP_UTF8, 0, wideModulePath.data(), static_cast<int>(wideLength),
						utf8ModulePath.data(), static_cast<int>(utf8ModulePath.size() - 1),
						nullptr, nullptr);
					if (utf8Length > 0) {
						utf8ModulePath[static_cast<std::size_t>(utf8Length)] = '\0';
						modulePath = utf8ModulePath.data();
					}
				}
			}

			logger::critical(
				"[RR][M3][native-pass-fault] first code=0x{:08X} flags=0x{:08X} "
				"exception=0x{:016X} av(present/op/address)={}/0x{:X}/0x{:016X} "
				"context(rip/rsp/rbp)=0x{:016X}/0x{:016X}/0x{:016X} "
				"phase={} phaseSeq={} "
				"virtualQuery(ok/allocationBase/type/imageRva)={}/0x{:016X}/0x{:08X}/0x{:X} "
				"module={}",
				snapshot.code, snapshot.flags, snapshot.exceptionAddress,
				snapshot.accessViolationParametersPresent,
				snapshot.accessViolationOperation, snapshot.accessViolationAddress,
				snapshot.rip, snapshot.rsp, snapshot.rbp,
				CapturePhaseName(snapshot.capturePhase), snapshot.capturePhaseSequence,
				snapshot.virtualQuerySucceeded, snapshot.allocationBase,
				snapshot.allocationType, snapshot.imageRva, modulePath);

			if (snapshot.depthProbeEnabled != 0) {
				const auto provenance = MirrorNativeDepthFaultProbe::Classify(
					snapshot.rdx, snapshot.depthProbe);
				logger::critical(
					"[RR][M3][native-depth-fault-probe] registers(rax/rcx/rdx/r8/r9)="
					"0x{:016X}/0x{:016X}/0x{:016X}/0x{:016X}/0x{:016X} "
					"expected(private/engine/index/slice/slotCaptured)="
					"0x{:016X}/0x{:016X}/{}/{}/{} provenance={} stackWords={}",
					snapshot.rax, snapshot.rcx, snapshot.rdx, snapshot.r8, snapshot.r9,
					snapshot.depthProbe.privateDSV,
					snapshot.depthProbe.engineTableDSV,
					snapshot.depthProbe.depthIndex,
					snapshot.depthProbe.depthSlice,
					snapshot.depthProbe.engineSlotCaptured,
					MirrorNativeDepthFaultProbe::Name(provenance),
					snapshot.stackCandidateCount);
				for (std::uint32_t index = 0;
					 index < snapshot.stackCandidateCount; ++index) {
					const auto candidate = snapshot.stackCandidates[index];
					MEMORY_BASIC_INFORMATION memory{};
					std::uint64_t allocationBase = 0;
					std::uint64_t imageRva = 0;
					std::uint32_t allocationType = 0;
					if (candidate != 0 && VirtualQuery(
							reinterpret_cast<const void*>(candidate), &memory,
							sizeof(memory)) == sizeof(memory)) {
						allocationBase = reinterpret_cast<std::uintptr_t>(
							memory.AllocationBase);
						allocationType = memory.Type;
						if ((memory.Type & MEM_IMAGE) != 0 && candidate >= allocationBase)
							imageRva = candidate - allocationBase;
					}
					logger::critical(
						"[RR][M3][native-depth-fault-probe][stack] [{}]="
						"0x{:016X} allocationBase=0x{:016X} type=0x{:08X} imageRva=0x{:X}",
						index, candidate, allocationBase, allocationType, imageRva);
				}
			}
		}

		using RootRelation = MirrorExteriorCaptureTopology::RootRelation;

		[[nodiscard]] bool ClassifyRootRelationSEH(
			RE::NiAVObject* candidate,
			RE::NiAVObject* referenceRoot,
			RootRelation& output) noexcept
		{
			output = RootRelation::kMalformed;
			if (!candidate || !referenceRoot)
				return false;
			if (candidate == referenceRoot) {
				output = RootRelation::kSame;
				return true;
			}

			__try {
				const auto parent = [](const RE::NiAVObject* object) noexcept
				{
					return static_cast<const RE::NiAVObject*>(object->parent);
				};
				const auto candidateToReference = PlayerPassAncestry::Classify(
					static_cast<const RE::NiAVObject*>(candidate),
					static_cast<const RE::NiAVObject*>(referenceRoot),
					kMaximumAuxiliaryRootParentDepth, parent);
				if (candidateToReference == PlayerPassAncestry::Result::kMatch) {
					output = RootRelation::kDescendantOfWorld;
					return true;
				}
				if (candidateToReference != PlayerPassAncestry::Result::kNoMatch)
					return true;

				const auto referenceToCandidate = PlayerPassAncestry::Classify(
					static_cast<const RE::NiAVObject*>(referenceRoot),
					static_cast<const RE::NiAVObject*>(candidate),
					kMaximumAuxiliaryRootParentDepth, parent);
				if (referenceToCandidate == PlayerPassAncestry::Result::kMatch) {
					output = RootRelation::kAncestorOfWorld;
					return true;
				}
				if (referenceToCandidate == PlayerPassAncestry::Result::kNoMatch)
					output = RootRelation::kIndependent;
				return true;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
		}

		/**
		 * Filter for READ-ONLY diagnostics. It records the code but must never set
		 * the global fault latch: a telemetry read that trips over engine state
		 * being mutated concurrently is not a reason to disable reflections for the
		 * rest of the session. Exactly that happened on 2026-08-07 - one access
		 * violation inside the batch-renderer inventory killed every mirror in the
		 * session - which is the same shape as the sibling project's guard
		 * false-positive, repeated here in the diagnostic instead of the guard.
		 */
		[[nodiscard]] int RecordDiagnosticException(unsigned long a_code) noexcept
		{
			g_lastDiagnosticException.store(a_code, std::memory_order_relaxed);
			return EXCEPTION_EXECUTE_HANDLER;
		}

		// Bounded by kMaxDrainInspectFaults plus one disable notice, so the
		// render thread emits at most a handful of these per session.
		void LogDrainInspectFaultNoexcept(
			unsigned long a_code, bool a_nowDisabled) noexcept
		{
			try {
				if (a_nowDisabled) {
					logger::warn(
						"[RR][M3] batch-inventory inspection faulted (SEH=0x{:08X}) and "
						"reached its fault budget; inventory telemetry disabled for this "
						"session, remaining drain gates continue uncorroborated",
						a_code);
				} else {
					logger::warn(
						"[RR][M3] batch-inventory inspection faulted (SEH=0x{:08X}); "
						"telemetry-only, private pass continues",
						a_code);
				}
			} catch (...) {
				// Diagnostics must never unwind through the render path.
			}
		}

		void LogBeginRollbackFailureNoexcept(unsigned long a_code) noexcept
		{
			try {
				logger::critical(
					"[RR][M3] private render-target Begin rollback failed (SEH=0x{:08X}); "
					"target remains retained",
					a_code);
			} catch (...) {
			}
		}

		[[nodiscard]] bool CopyCodeWindowSEH(
			std::uintptr_t a_address,
			std::uint8_t* a_output,
			std::size_t a_size) noexcept
		{
			if (!a_address || !a_output || a_size == 0)
				return false;
			__try {
				std::memcpy(a_output, reinterpret_cast<const void*>(a_address), a_size);
				return true;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
		}

		[[nodiscard]] bool IsExecutableAddress(const void* a_address) noexcept
		{
			if (!a_address)
				return false;
			MEMORY_BASIC_INFORMATION info{};
			if (VirtualQuery(a_address, &info, sizeof(info)) != sizeof(info) ||
				info.State != MEM_COMMIT || (info.Protect & PAGE_GUARD) != 0 ||
				(info.Protect & PAGE_NOACCESS) != 0) {
				return false;
			}
			const DWORD protection = info.Protect & 0xFF;
			return protection == PAGE_EXECUTE || protection == PAGE_EXECUTE_READ ||
			       protection == PAGE_EXECUTE_READWRITE ||
			       protection == PAGE_EXECUTE_WRITECOPY;
		}

		[[nodiscard]] bool ValidateFiveByteBranchStubSEH(
			std::uintptr_t a_branchTarget,
			std::uintptr_t a_expectedDestination) noexcept
		{
			if (!a_branchTarget || !a_expectedDestination ||
				!IsExecutableAddress(reinterpret_cast<const void*>(a_branchTarget)) ||
				!IsExecutableAddress(reinterpret_cast<const void*>(a_expectedDestination))) {
				return false;
			}
			std::array<std::uint8_t,
				MirrorPaneDeliverySignature::kFiveByteBranchStubSize> stub{};
			return CopyCodeWindowSEH(a_branchTarget, stub.data(), stub.size()) &&
			       MirrorPaneDeliverySignature::MatchesFiveByteBranchStub(
				       stub, static_cast<std::uint64_t>(a_expectedDestination));
		}

		// Exact runtimes whose private-pass machinery (hooks, raw offsets, phase
		// assumptions) is validated: SE 1.5.97, AE 1.6.1170 / 1.7.104 and, since
		// 2026-09-04, Skyrim VR 1.4.15.  Every VR layout difference is selected
		// through the runtime layout tables near the top of this file; the few
		// sites that still depend on a flat-only layout say so next to their use.
		[[nodiscard]] bool IsSupportedRuntime() noexcept
		{
			const auto version = REL::Module::get().version();
			return (REL::Module::IsSE() && version == REL::Version{ 1, 5, 97, 0 }) ||
			       (REL::Module::IsAE() && SupportedRuntimePolicy::IsSupportedAEVersion(version)) ||
			       SupportedRuntimePolicy::IsExactVRRuntime();
		}

		[[nodiscard]] HandMirrorUnifiedCullRuntimePolicy::Runtime
		ExactHandUnifiedCullRuntime() noexcept
		{
			const auto version = REL::Module::get().version();
			if (REL::Module::IsSE() && version == REL::Version{ 1, 5, 97, 0 }) {
				return HandMirrorUnifiedCullRuntimePolicy::Runtime::kSkyrimSE1597;
			}
			if (SupportedRuntimePolicy::IsExactAE17104Runtime()) {
				return HandMirrorUnifiedCullRuntimePolicy::Runtime::kSkyrimAE17104;
			}
			if (REL::Module::IsAE() &&
				SupportedRuntimePolicy::IsSupportedAEVersion(version)) {
				return HandMirrorUnifiedCullRuntimePolicy::Runtime::kSkyrimAE161170;
			}
			if (SupportedRuntimePolicy::IsExactVRRuntime()) {
				return HandMirrorUnifiedCullRuntimePolicy::Runtime::kSkyrimVR1415;
			}
			return HandMirrorUnifiedCullRuntimePolicy::Runtime::kUnsupported;
		}

		[[nodiscard]] bool VerifyHandUnifiedCullRuntimeContract() noexcept
		{
			namespace Policy = HandMirrorUnifiedCullRuntimePolicy;
			const auto runtime = ExactHandUnifiedCullRuntime();
			const auto* contract = Policy::Select(runtime);
			if (!contract)
				return false;

			const auto base = REL::Module::get().base();
			const bool vr = runtime == Policy::Runtime::kSkyrimVR1415;
			// The VR address library carries none of the NiAVObject::Cull /
			// NiNode::OnVisible / BSCullingProcess IDs (and maps some others to
			// non-function addresses), so the VR contract's RVAs are authoritative
			// there.  Flat runtimes resolve through the library and the RVA
			// cross-check below stays a real check; on VR it is an identity.
			const auto resolve = [&](const std::uint64_t a_id,
									 const std::uintptr_t a_rva) -> std::uintptr_t {
				if (contract->rvaAuthoritative)
					return a_rva != 0 ? base + a_rva : 0;
				return REL::ID(a_id).address();
			};
			const auto initializer = resolve(
				contract->initializeDescriptorID, contract->initializeDescriptorRVA);
			const auto cullFromDescriptor = resolve(
				contract->cullFromDescriptorID, contract->cullFromDescriptorRVA);
			const auto objectCull = resolve(
				contract->niAVObjectCullID, contract->niAVObjectCullRVA);
			const auto nodeOnVisible = resolve(
				contract->niNodeOnVisibleID, contract->niNodeOnVisibleRVA);
			const auto finalizeCollection = resolve(
				contract->finalizeCollectionID, contract->finalizeCollectionRVA);
			// VR clears the collection through a virtual slot; there is no direct
			// clear target to resolve or decode.
			const auto clearCollection = contract->clearIsVirtual ?
				std::uintptr_t{ 0 } :
				resolve(contract->clearCollectionID, contract->clearCollectionRVA);
			if (!initializer || !cullFromDescriptor || !objectCull ||
				!nodeOnVisible || !finalizeCollection ||
				initializer != base + contract->initializeDescriptorRVA ||
				cullFromDescriptor != base + contract->cullFromDescriptorRVA ||
				objectCull != base + contract->niAVObjectCullRVA ||
				nodeOnVisible != base + contract->niNodeOnVisibleRVA ||
				finalizeCollection != base + contract->finalizeCollectionRVA ||
				(!contract->clearIsVirtual &&
					(!clearCollection ||
						clearCollection != base + contract->clearCollectionRVA))) {
				return false;
			}

			const auto initializerExpected =
				Policy::DescriptorInitializerBytes(runtime);
			const auto cullPrologueExpected = Policy::CullPrologueBytes(runtime);
			const auto objectCullExpected = Policy::NiAVObjectCullBytes(runtime);
			const std::size_t routeZeroSize = Policy::RouteZeroWindowSize(runtime);
			constexpr std::size_t kMaximumWindow = 128;
			if (initializerExpected.empty() ||
				initializerExpected.size() > kMaximumWindow ||
				cullPrologueExpected.empty() ||
				cullPrologueExpected.size() > kMaximumWindow ||
				objectCullExpected.empty() ||
				objectCullExpected.size() > kMaximumWindow ||
				routeZeroSize == 0 || routeZeroSize > kMaximumWindow) {
				return false;
			}
			std::array<std::uint8_t, kMaximumWindow> initializerBytes{};
			std::array<std::uint8_t, kMaximumWindow> cullPrologue{};
			std::array<std::uint8_t, kMaximumWindow> objectCullBytes{};
			std::array<std::uint8_t, Policy::kChildCullWindow.size()>
				childCullWindow{};
			std::array<std::uint8_t, kMaximumWindow> routeZeroWindow{};
			const auto childWindowAddress =
				nodeOnVisible + contract->childCullWindowOffset;
			const auto routeZeroAddress =
				cullFromDescriptor + contract->routeZeroWindowOffset;
			if (!CopyCodeWindowSEH(
					initializer, initializerBytes.data(), initializerExpected.size()) ||
				!CopyCodeWindowSEH(
					cullFromDescriptor, cullPrologue.data(),
					cullPrologueExpected.size()) ||
				!CopyCodeWindowSEH(
					objectCull, objectCullBytes.data(), objectCullExpected.size()) ||
				!CopyCodeWindowSEH(
					childWindowAddress, childCullWindow.data(),
					childCullWindow.size()) ||
				!CopyCodeWindowSEH(
					routeZeroAddress, routeZeroWindow.data(), routeZeroSize) ||
				!Policy::MatchesExact(
					std::span<const std::uint8_t>{
						initializerBytes.data(), initializerExpected.size() },
					initializerExpected) ||
				!Policy::MatchesExact(
					std::span<const std::uint8_t>{
						cullPrologue.data(), cullPrologueExpected.size() },
					cullPrologueExpected) ||
				(!MirrorScenePruning::OwnsHook(objectCull) && !Policy::MatchesExact(
					std::span<const std::uint8_t>{
						objectCullBytes.data(), objectCullExpected.size() },
					objectCullExpected)) ||
				!Policy::MatchesChildCullWindow(childCullWindow) ||
				!Policy::MatchesRouteZeroWindowFor(
					runtime,
					std::span<const std::uint8_t>{
						routeZeroWindow.data(), routeZeroSize })) {
				return false;
			}

			std::uintptr_t childCullTarget = 0;
			std::uintptr_t finalizeTarget = 0;
			std::uintptr_t clearTarget = 0;
			const std::size_t finalizeCallOffset =
				vr ? Policy::kVRFinalizeCallOffset : Policy::kFinalizeCallOffset;
			if (!ReadCallTargetSEH(
					childWindowAddress + Policy::kChildCullCallOffset,
					childCullTarget) ||
				childCullTarget != objectCull ||
				!ReadCallTargetSEH(
					routeZeroAddress + finalizeCallOffset, finalizeTarget) ||
				finalizeTarget != finalizeCollection) {
				return false;
			}
			if (contract->clearIsVirtual) {
				// The `FF 90 D0 00 00 00` virtual-clear tail (vtable slot
				// clearVirtualSlot) already matched byte-exactly above.
				return true;
			}
			return ReadCallTargetSEH(
					   routeZeroAddress + Policy::kClearCallOffset, clearTarget) &&
			       clearTarget == clearCollection;
		}

		[[nodiscard]] fs::path MarkerPath(std::wstring_view a_marker)
		{
			std::array<wchar_t, 32768> executablePath{};
			const DWORD length = GetModuleFileNameW(
				nullptr, executablePath.data(), static_cast<DWORD>(executablePath.size()));
			if (length == 0 || length >= executablePath.size())
				return fs::path{ L"Data" } / std::wstring{ a_marker };
			return fs::path{ std::wstring_view{ executablePath.data(), length } }.parent_path() /
			       L"Data" / std::wstring{ a_marker };
		}

		[[nodiscard]] bool InspectAuxiliaryMarker(
			std::wstring_view a_marker,
			const char* a_label) noexcept
		{
			if (MirrorFeatures::Enabled(a_marker)) return true;
			try {
				const fs::path path = MarkerPath(a_marker);
				std::error_code error{};
				const bool present = fs::exists(path, error);
				if (error) {
					logger::error(
						"[RR][Planar] could not inspect {} marker {}: {}",
						a_label, path.string(), error.message());
					return false;
				}
				return present;
			} catch (...) {
				logger::error(
					"[RR][Planar] exception while resolving {} marker path", a_label);
				return false;
			}
		}

		[[nodiscard]] bool InspectExactEmptyAuxiliaryMarker(
			std::wstring_view a_marker,
			const char* a_label) noexcept
		{
			if (MirrorFeatures::Enabled(a_marker)) return true;
			try {
				const fs::path path = MarkerPath(a_marker);
				const HANDLE file = CreateFileW(
					path.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING,
					FILE_ATTRIBUTE_NORMAL | FILE_FLAG_OPEN_REPARSE_POINT, nullptr);
				if (file == INVALID_HANDLE_VALUE)
					return false;

				FILE_ATTRIBUTE_TAG_INFO tag{};
				FILE_STANDARD_INFO standard{};
				const bool accepted = GetFileType(file) == FILE_TYPE_DISK &&
					GetFileInformationByHandleEx(
						file, FileAttributeTagInfo, &tag, sizeof(tag)) &&
					GetFileInformationByHandleEx(
						file, FileStandardInfo, &standard, sizeof(standard)) &&
					(tag.FileAttributes &
						(FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY |
							FILE_ATTRIBUTE_DEVICE)) == 0 &&
					!standard.Directory && standard.EndOfFile.QuadPart == 0;
				(void)CloseHandle(file);
				if (!accepted) {
					logger::error(
						"[RR][Planar] {} marker {} rejected; expected an exact empty regular non-reparse file",
						a_label, path.string());
				}
				return accepted;
			} catch (...) {
				logger::error(
					"[RR][Planar] exception while resolving exact {} marker path",
					a_label);
				return false;
			}
		}

		[[nodiscard]] ID3D11Device* Device() noexcept
		{
			return reinterpret_cast<ID3D11Device*>(RE::BSGraphics::Renderer::GetDevice());
		}

		[[nodiscard]] HRESULT DeviceRemovedReasonSEH() noexcept
		{
			__try {
				if (auto* device = Device()) return device->GetDeviceRemovedReason();
				return S_OK; // A not-yet-created device is handled by normal admission.
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				return E_UNEXPECTED;
			}
		}

		[[nodiscard]] bool DeviceLossStopsCapture() noexcept
		{
			if (!g_deviceLossGuardEnabled.load(std::memory_order_relaxed))
				return false;
			if (g_deviceLossObserved.load(std::memory_order_acquire))
				return true;
			const HRESULT reason = DeviceRemovedReasonSEH();
			if (reason == S_OK) return false;
			LatchFault(__LINE__);
			if (!g_deviceLossObserved.exchange(true, std::memory_order_acq_rel)) {
				try {
					logger::critical("[RR][device-loss] stopping private capture and subsequent batch dispatch: HRESULT=0x{:08X}; native GPU queries remain untouched",
						static_cast<std::uint32_t>(reason));
				} catch (...) {}
			}
			// The caller's existing finally blocks still own all restoration. Do
			// not release targets or alter native upload-ring/query state here.
			return true;
		}

		[[nodiscard]] ID3D11DeviceContext* Context() noexcept
		{
			const auto* data = RE::BSGraphics::Renderer::GetRendererDataSingleton();
			return data ? reinterpret_cast<ID3D11DeviceContext*>(data->context) : nullptr;
		}

		[[nodiscard]] bool ResetExteriorDepthForPrimarySEH() noexcept
		{
			bool reset = false;
			__try {
				auto* const target = g_activeTarget;
				auto* const context = Context();
				reset = target && context && target->ClearDepthStencil(context);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				reset = false;
			}
			if (reset) {
				g_counters.mirrorExteriorDepthResets.fetch_add(
					1, std::memory_order_relaxed);
			} else {
				g_counters.mirrorExteriorDepthResetFailures.fetch_add(
					1, std::memory_order_relaxed);
			}
			return reset;
		}

		void PrepareNativeDepthFaultProbeCapture() noexcept
		{
			g_nativeDepthFaultProbeCapture = {};
			if (!g_nativeDepthFaultProbeEnabled.load(std::memory_order_relaxed))
				return;

			__try {
				auto* const target = g_activeTarget;
				auto* const shadowState = RE::BSGraphics::RendererShadowState::GetSingleton();
				auto* const renderer = RE::BSGraphics::Renderer::GetSingleton();
				if (!target || !shadowState || !renderer)
					return;

				MirrorNativeDepthFaultProbe::Capture capture{};
				capture.privateDSV = reinterpret_cast<std::uintptr_t>(target->DepthDSV());
				const auto& flat = shadowState->GetRuntimeData();
				capture.depthIndex = flat.depthStencil;
				capture.depthSlice = flat.depthStencilSlice;
				capture.engineSlotCaptured =
					MirrorNativeDepthFaultProbe::IsEngineSlotBounded(
						capture.depthIndex, capture.depthSlice,
						static_cast<std::uint32_t>(
							RE::RENDER_TARGETS_DEPTHSTENCIL::kTOTAL));
				if (capture.engineSlotCaptured) {
					auto& depthData = renderer->GetDepthStencilData();
					capture.engineTableDSV = reinterpret_cast<std::uintptr_t>(
						depthData.depthStencils[capture.depthIndex].views[capture.depthSlice]);
				}
				g_nativeDepthFaultProbeCapture = capture;
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				g_nativeDepthFaultProbeCapture = {};
			}
		}

		MirrorFleetRuntime::CaptureTargetPool g_fleetTargetPool;
		// On-screen sizing (owner, 2026-09-17: "Size captures to the mirror on
		// screen"). Set around the placed capture's EnsureRenderObjects only; 0
		// leaves the frame batch's resolution in charge. Render thread.
		MirrorScreenSizePolicy::Extent g_placedCaptureExtent{};
		MirrorScreenSizePolicy::Sizer g_screenSizer;
		std::atomic<int> g_lastPlacedCaptureWidth{ 0 }, g_lastPlacedCaptureHeight{ 0 };
		std::atomic<std::uint64_t> g_screenSizeChoices{}, g_screenSizeRaises{}, g_screenSizeLowers{},
			g_screenSizeUnknown{};
		std::atomic<int> g_screenSizeNeedWidth{}, g_screenSizeNeedHeight{};

		[[nodiscard]] MirrorScreenSizePolicy::Pixels ProjectedPanePixels(const PlanarMirrorMath::PaneFit& a_pane) noexcept
		{
			MirrorPaneDelivery::DeferredCaptureMainView view{};
			if (!MirrorPaneDelivery::TryGetDeferredCaptureMainView(view) || !view.valid)
				return {};
			// The larger of the main render size and the output: detail an upscaler
			// reconstructs up to the output resolution is kept.
			std::uint32_t outputWidth{}, outputHeight{};
			(void)MirrorFleetRuntime::OutputSize(outputWidth, outputHeight);
			const float width = (std::max)(view.viewport.Width, static_cast<float>(outputWidth));
			const float height = (std::max)(view.viewport.Height, static_cast<float>(outputHeight));
			const MirrorScreenSizePolicy::Pane pane{ a_pane.center, a_pane.tangent, a_pane.bitangent,
				a_pane.halfTangent, a_pane.halfBitangent };
			return MirrorScreenSizePolicy::ProjectedPixels(pane, view.viewProjection, view.origin, width, height);
		}

		// Owner, 2026-09-17: captures sized to the pane on screen, and (core run 9)
		// shaped like it. {0,0} leaves the frame batch's square resolution in charge.
		[[nodiscard]] MirrorScreenSizePolicy::Extent ChoosePlacedCaptureExtent(std::uint32_t a_formID,
			const PlanarMirrorMath::PaneFit& a_pane) noexcept
		{
			const int cap = g_multiMirrorFrameBatch.quality.resolution;
			if (!MirrorCaptureOptimizations::screenSizedCapture.load(std::memory_order_relaxed))
				return {};
			MirrorScreenSizePolicy::Pixels pixels{};
			try {
				pixels = ProjectedPanePixels(a_pane);
			} catch (...) {
				pixels = {};
			}
			const auto extent = g_screenSizer.Choose(a_formID, cap, pixels, MirrorFleetRuntime::Now(),
				MirrorCaptureOptimizations::rectangularCapture.load(std::memory_order_relaxed),
				MirrorScreenSizePolicy::Supersample());
			const auto& counters = g_screenSizer.Read();
			g_screenSizeChoices.store(counters.choices, std::memory_order_relaxed);
			g_screenSizeRaises.store(counters.raises, std::memory_order_relaxed);
			g_screenSizeLowers.store(counters.lowers, std::memory_order_relaxed);
			g_screenSizeUnknown.store(counters.unknown, std::memory_order_relaxed);
			g_screenSizeNeedWidth.store(counters.lastNeed.width, std::memory_order_relaxed);
			g_screenSizeNeedHeight.store(counters.lastNeed.height, std::memory_order_relaxed);
			return extent;
		}
		bool FleetColourOnly() noexcept
		{
			return MirrorFleetPolicy::enabled.load(std::memory_order_relaxed) && MirrorFramePublication::MultiMirrorEnabled();
		}
		// choices/raises/lowers/unknown, need width/height, size width/height.
		[[nodiscard]] std::uint64_t ScreenSizeCounter(int a_index) noexcept
		{
			switch (a_index) {
			case 0: return g_screenSizeChoices.load(std::memory_order_relaxed);
			case 1: return g_screenSizeRaises.load(std::memory_order_relaxed);
			case 2: return g_screenSizeLowers.load(std::memory_order_relaxed);
			case 3: return g_screenSizeUnknown.load(std::memory_order_relaxed);
			case 4: return static_cast<std::uint64_t>(g_screenSizeNeedWidth.load(std::memory_order_relaxed));
			case 5: return static_cast<std::uint64_t>(g_screenSizeNeedHeight.load(std::memory_order_relaxed));
			case 6: return static_cast<std::uint64_t>(g_lastPlacedCaptureWidth.load(std::memory_order_relaxed));
			case 7: return static_cast<std::uint64_t>(g_lastPlacedCaptureHeight.load(std::memory_order_relaxed));
			default: break;
			}
			return 0;
		}
		[[nodiscard]] bool RefreshCaptureSizing() noexcept
		{
			if (PeerDetection::ENBPresent()) {
				MirrorCaptureSizing::Extent extent{};
				__try {
					auto* window = RE::BSGraphics::Renderer::GetCurrentRenderWindow();
					auto* chain = window ? reinterpret_cast<IDXGISwapChain*>(window->swapChain) : nullptr;
					DXGI_SWAP_CHAIN_DESC description{};
					if (chain && SUCCEEDED(chain->GetDesc(&description)))
						extent = { description.BufferDesc.Width, description.BufferDesc.Height };
				} __except (EXCEPTION_EXECUTE_HANDLER) { }
				const auto previous = MirrorCaptureSizing::ForSquare(0);
				MirrorCaptureSizing::SetFramebuffer(true, extent);
				if (extent.Valid() && previous != extent)
					logger::info("[MOS][CaptureSize] ENB framebuffer={}x{}; standing and hand captures use this extent", extent.width, extent.height);
				return extent.Valid();
			}
			MirrorCaptureSizing::SetFramebuffer(false, {});
			return true;
		}

		[[nodiscard]] bool EnsureRenderObjects(
			RenderTarget*& a_targetSlot,
			RenderTarget::DebugChannel a_debugChannel) noexcept
		{
			if (!RefreshCaptureSizing() || !g_owner.EnsureCreated())
				return false;
			if (g_mirrorSupplementalActorCycleEnabled.load(std::memory_order_acquire) &&
				!g_supplementalActorOwner.EnsureCreated())
				return false;
			if (!a_targetSlot)
				a_targetSlot = new (std::nothrow) RenderTarget();
			if (!a_targetSlot)
				return false;
			const std::uint32_t targetDimension =
				g_targetDimension.load(std::memory_order_acquire);
			if (FleetColourOnly()) {
				const auto beforeColour = g_fleetTargetPool.ColourAllocations();
				const auto beforeDepth = g_fleetTargetPool.DepthAllocations();
				const bool ready = MirrorCaptureSizing::UsesFramebuffer() ?
					g_fleetTargetPool.EnsureFramebuffer(a_targetSlot, Device(),
						MirrorCaptureSizing::ForSquare(0), a_debugChannel, g_mirrorTargetGeneration) :
					g_fleetTargetPool.Ensure(a_targetSlot, Device(),
						g_placedCaptureExtent.width > 0 ?
							MirrorCaptureSizing::Extent{ static_cast<std::uint32_t>(g_placedCaptureExtent.width),
								static_cast<std::uint32_t>(g_placedCaptureExtent.height) } :
							MirrorCaptureSizing::Extent{ static_cast<std::uint32_t>(g_multiMirrorFrameBatch.quality.resolution),
								static_cast<std::uint32_t>(g_multiMirrorFrameBatch.quality.resolution) },
						a_debugChannel, g_mirrorTargetGeneration, PeerDetection::CommunityShadersPresent());
				if (g_fleetTargetPool.ColourAllocations() != beforeColour)
					MirrorFleetRuntime::Allocated(g_fleetTargetPool.DepthAllocations() != beforeDepth);
				return ready;
			}
			if (!a_targetSlot->Ready() &&
				!a_targetSlot->Create(
					Device(), targetDimension, targetDimension,
					DXGI_FORMAT_R16G16B16A16_FLOAT, a_debugChannel))
				return false;
			return true;
		}

		[[nodiscard]] bool EnsureRenderObjectsSEH(
			RenderTarget*& a_targetSlot,
			RenderTarget::DebugChannel a_debugChannel) noexcept
		{
			bool result = false;
			__try {
				result = EnsureRenderObjects(a_targetSlot, a_debugChannel);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				result = false;
			}
			return result;
		}

		[[nodiscard]] bool EnsureHandMirrorTargets() noexcept
		{
			if (!RefreshCaptureSizing() || !g_owner.EnsureCreated() || !Device())
				return false;
			const auto targetDimension = HandMirrorReflectionRuntime::PrivateTargetDimension();
			const auto targetHeight = HandMirrorReflectionRuntime::PrivateTargetHeight();
			const auto reducedViews = HandMirrorReflectionRuntime::PrivateTargetReducedViews();
			for (std::size_t role = 0; role < g_handMirrorTargets.size(); ++role) {
				auto*& target = g_handMirrorTargets[role];
				if (!target)
					target = new (std::nothrow) RenderTarget();
				if (!target)
					return false;
				// Owner menu changed the hand resolution (512-4096): re-create the
				// backing target once it is unbound; a bound target waits a frame. The
				// new generation retires publications of the old identity.
				if (target->Ready() &&
					(target->AllocatedWidth() != targetDimension ||
						target->AllocatedHeight() != targetHeight ||
						target->ReducedViewCount() != reducedViews)) {
					if (target->Bound())
						return false;
					target->Release();
					if (target->LastRestoreStatus() == RenderTarget::RestoreStatus::kFault)
						return false;
					g_counters.handTargetReallocations.fetch_add(1, std::memory_order_relaxed);
				}
				if (!target->Ready()) {
					if (g_handMirrorTargetGenerationCursor ==
						(std::numeric_limits<std::uint64_t>::max)()) {
						return false;
					}
					const auto channel = role == 0 ?
						RenderTarget::DebugChannel::kMirror :
						RenderTarget::DebugChannel::kMirrorAlternate;
					if (!target->Create(
							Device(),
							targetDimension,
							targetHeight,
							DXGI_FORMAT_R16G16B16A16_FLOAT, channel,
							static_cast<std::uint32_t>(role),
							nullptr,
							reducedViews)) {
						return false;
					}
					g_handMirrorTargetGenerations[role] =
						++g_handMirrorTargetGenerationCursor;
				}
				if (target->AllocatedWidth() != targetDimension ||
					target->AllocatedHeight() != targetHeight ||
					target->ColorFormat() != DXGI_FORMAT_R16G16B16A16_FLOAT ||
					target->ColorMipLevels() !=
						HandMirrorReflectionRuntime::PrivateTargetMipLevels() - target->RenderMip() ||
					!target->ColorMipGenerationSupported() ||
					g_handMirrorTargetGenerations[role] == 0) {
					return false;
				}
			}
			if (g_handPhysicalFragmentClipEnabled.load(
					std::memory_order_acquire) &&
				!HandMirrorPhysicalClipDepth::EnsureDevice(Device())) {
				return false;
			}
			return true;
		}

		[[nodiscard]] bool EnsureHandMirrorTargetsSEH() noexcept
		{
			bool ready = false;
			__try {
				ready = EnsureHandMirrorTargets();
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				ready = false;
			}
			return ready;
		}

		[[nodiscard]] HandMirrorInternalPublicationStore::Store::PhysicalTargets
		HandMirrorPhysicalTargets() noexcept
		{
			HandMirrorInternalPublicationStore::Store::PhysicalTargets output{};
			for (std::size_t role = 0; role < output.size(); ++role) {
				const auto* target = g_handMirrorTargets[role];
				if (!target || !target->Ready())
					return {};
				output[role] = {
					g_handMirrorTargetGenerations[role],
					reinterpret_cast<std::uint64_t>(
						target->ColorResourceIdentity()),
					reinterpret_cast<std::uint64_t>(
						target->DepthResourceIdentity())
				};
			}
			if (!HandMirrorRuntimeBridgePolicy::ArePrivateTargetsPhysicallyDisjoint(
					output[0], output[1])) {
				return {};
			}
			return output;
		}

		[[nodiscard]] RenderTarget* HandMirrorTargetForIdentity(
			const HandMirrorRuntimeBridgePolicy::PrivateTargetIdentity& identity)
			noexcept
		{
			const auto targets = HandMirrorPhysicalTargets();
			for (std::size_t role = 0; role < targets.size(); ++role) {
				if (targets[role] == identity)
					return g_handMirrorTargets[role];
			}
			return nullptr;
		}

		[[nodiscard]] bool EnsureWallTargetGeneration(
			RenderTarget* target,
			std::uint64_t& generation) noexcept
		{
			if (!target || !target->Ready())
				return false;
			if (generation == 0) {
				if (g_mirrorTargetGenerationCursor ==
					(std::numeric_limits<std::uint64_t>::max)()) {
					return false;
				}
				generation = ++g_mirrorTargetGenerationCursor;
			}
			return true;
		}

		[[nodiscard]] HandMirrorRuntimeBridgePolicy::PrivateTargetIdentity
		WallTargetIdentity(
			const RenderTarget* target,
			const std::uint64_t generation) noexcept
		{
			if (!target || !target->Ready() || generation == 0)
				return {};
			return {
				generation,
				reinterpret_cast<std::uint64_t>(target->ColorResourceIdentity()),
				reinterpret_cast<std::uint64_t>(target->DepthResourceIdentity())
			};
		}


		

		

		[[nodiscard]] bool TryGetWorldRootCamera(RE::NiCamera*& output) noexcept
		{
			__try {
				output = RE::Main::WorldRootCamera();
				return true;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				output = nullptr;
				return false;
			}
		}

		[[nodiscard]] bool ReadCameraNearPlaneSEH(
			const RE::NiCamera* a_camera,
			float& a_output) noexcept
		{
			a_output = 0.0f;
			__try {
				if (!a_camera)
					return false;
				a_output = a_camera->GetNearPlane();
				return std::isfinite(a_output) && a_output > 0.0f;
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				a_output = 0.0f;
				return false;
			}
		}

		struct MirrorLocationGateSnapshot
		{
			MirrorInteriorEligibility::Observation observation{};
			MirrorInteriorEligibility::LocationIdentity location{};
			bool readFault{ false };
		};

		[[nodiscard]] MirrorInteriorEligibility::Status ReadMirrorLocationStatusSEH(
			MirrorLocationGateSnapshot& a_snapshot) noexcept
		{
			a_snapshot = {};
			__try {
				// Use only CommonLib's typed current-world/current-reference routes.
				// No renderer or terrain address is introduced by this containment.
				auto* world = RE::TES::GetSingleton();
				a_snapshot.observation.worldAvailable = world != nullptr;
				auto* player = RE::PlayerCharacter::GetSingleton();
				a_snapshot.observation.playerAvailable = player != nullptr;

				auto* worldInterior = world ? world->interiorCell : nullptr;
				a_snapshot.observation.worldInteriorPresent = worldInterior != nullptr;
				if (worldInterior) {
					a_snapshot.observation.worldInteriorFlag =
						worldInterior->IsInteriorCell();
					a_snapshot.observation.worldInteriorAttached =
						worldInterior->IsAttached();
				}

				auto* playerCell = player ? player->GetParentCell() : nullptr;
				a_snapshot.observation.playerCellPresent = playerCell != nullptr;
				if (playerCell) {
					a_snapshot.location.playerCell.address =
						reinterpret_cast<std::uintptr_t>(playerCell);
					a_snapshot.location.playerCell.formID = playerCell->GetFormID();
					a_snapshot.observation.playerCellInteriorFlag =
						playerCell->IsInteriorCell();
					a_snapshot.observation.playerCellAttached = playerCell->IsAttached();
				}
				a_snapshot.observation.sameCell =
					worldInterior && playerCell && worldInterior == playerCell;

				auto* playerWorldSpace = player ? player->GetWorldspace() : nullptr;
				a_snapshot.observation.playerWorldSpacePresent =
					playerWorldSpace != nullptr;
				if (playerWorldSpace) {
					a_snapshot.location.worldspace.address =
						reinterpret_cast<std::uintptr_t>(playerWorldSpace);
					a_snapshot.location.worldspace.formID = playerWorldSpace->GetFormID();
				}
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				a_snapshot.readFault = true;
			}

			return a_snapshot.readFault ?
			           MirrorInteriorEligibility::Status::kUnavailable :
			           MirrorInteriorEligibility::Classify(a_snapshot.observation);
		}

		[[nodiscard]] constexpr PlanarCaptureOpportunityPolicy::MirrorLocationKey
		ToCaptureLocationKey(
			MirrorInteriorEligibility::Status a_status,
			const MirrorInteriorEligibility::LocationIdentity& a_location) noexcept
		{
			switch (a_status) {
			case MirrorInteriorEligibility::Status::kInterior:
				return {
					PlanarCaptureOpportunityPolicy::MirrorLocationKind::kInterior,
					a_location.playerCell.formID,
					0
				};
			case MirrorInteriorEligibility::Status::kExterior:
				return {
					PlanarCaptureOpportunityPolicy::MirrorLocationKind::kExterior,
					0,
					a_location.worldspace.formID
				};
			case MirrorInteriorEligibility::Status::kUnavailable:
			default:
				return {};
			}
		}

		

		

		

		/**
		 * Indoors the mirror must live in the player's exact attached cell.
		 * Outdoors there is no single owning cell for a view, so the candidate is
		 * validated against its OWN parent cell instead - recognition has already
		 * proved it is loaded, 3D-ready and in range.
		 */
		[[nodiscard]] bool MirrorMatchesStableLocation(
			const MirrorRecognition::ActiveMirror& a_mirror,
			MirrorInteriorEligibility::Status a_status,
			const MirrorInteriorEligibility::LocationIdentity& a_location) noexcept
		{
			if (!MirrorInteriorEligibility::AllowsMirrorCapture(a_status))
				return false;
			if (MirrorInteriorEligibility::RequiresCellIdentity(a_status)) {
				if (!MirrorInteriorEligibility::SameValidCell(
						a_mirror.parentCell, a_location.playerCell)) {
					return false;
				}
			}
			return MirrorRecognition::IsCandidateCurrentAtLocation(
				a_mirror.formID, a_mirror.candidateGeneration, a_status, a_location);
		}

		[[nodiscard]] bool RevalidateMirrorLocation(
			const MirrorRecognition::ActiveMirror& a_mirror,
			MirrorInteriorEligibility::Status a_retainedStatus,
			const MirrorInteriorEligibility::LocationIdentity& a_retainedLocation,
			MirrorLocationGateSnapshot& a_currentSnapshot) noexcept
		{
			const auto currentStatus =
				ReadMirrorLocationStatusSEH(a_currentSnapshot);
			return MirrorInteriorEligibility::RevalidationAccepts(
				       a_retainedStatus, a_retainedLocation, currentStatus,
				       a_currentSnapshot.location) &&
			       MirrorMatchesStableLocation(
				       a_mirror, currentStatus, a_currentSnapshot.location);
		}

		void LogMirrorLocationRevalidationRejectNoexcept(
			const char* a_phase,
			const MirrorRecognition::ActiveMirror& a_mirror,
			const MirrorInteriorEligibility::LocationIdentity& a_retainedLocation,
			const MirrorLocationGateSnapshot& a_currentSnapshot) noexcept
		{
			if (g_loggedFirstMirrorInteriorRevalidationReject.exchange(
					true, std::memory_order_relaxed)) {
				return;
			}
			try {
				logger::warn(
					"[RR][M3] mirror {:08X} generation={} location changed at {}: "
					"retainedCell(address=0x{:016X}, form={:08X}) retainedWorld(address=0x{:016X}, form={:08X}) "
					"currentCell(address=0x{:016X}, form={:08X}) currentWorld(address=0x{:016X}, form={:08X}) "
					"mirrorParent(address=0x{:016X}, form={:08X})",
					a_mirror.formID, a_mirror.candidateGeneration,
					a_phase ? a_phase : "unknown",
					a_retainedLocation.playerCell.address,
					a_retainedLocation.playerCell.formID,
					a_retainedLocation.worldspace.address,
					a_retainedLocation.worldspace.formID,
					a_currentSnapshot.location.playerCell.address,
					a_currentSnapshot.location.playerCell.formID,
					a_currentSnapshot.location.worldspace.address,
					a_currentSnapshot.location.worldspace.formID,
					a_mirror.parentCell.address, a_mirror.parentCell.formID);
			} catch (...) {
			}
		}

		template <class SourcePlane>
		[[nodiscard]] PlanarMirrorMath::Plane ToMirrorMathPlane(
			const SourcePlane& a_source) noexcept
		{
			return {
				.normal = a_source.normal,
				.distance = a_source.distance
			};
		}

		template <class SourceSelection>
		[[nodiscard]] PlanarMirrorMath::PlaneSelection ToMirrorMathSelection(
			const SourceSelection& a_source) noexcept
		{
			return {
				.plane = ToMirrorMathPlane(a_source.plane),
				.center = a_source.center,
				.authoredNormal = a_source.authoredNormal,
				.tangent = a_source.tangent,
				.bitangent = a_source.bitangent,
				.normalAxis = a_source.normalAxis,
				.facingCosine = a_source.facingCosine,
				.confidence = a_source.confidence,
				.viewOriented = a_source.viewOriented,
				.renderable = a_source.renderable
			};
		}

		[[nodiscard]] bool MirrorCaptureClearanceAccepted(
			const RE::NiCamera* a_sourceCamera,
			const MirrorCameraOverride::CameraPose& a_sourcePose,
			const MirrorRecognition::ActiveMirror& a_mirror,
			PlanarMirrorMath::MirrorCaptureClearance& a_clearance,
			float& a_cameraNearPlane,
			float& a_normalHalfThickness) noexcept
		{
			a_clearance = {};
			a_cameraNearPlane = 0.0f;
			a_normalHalfThickness = 0.0f;
			const auto normalAxis = a_mirror.plane.normalAxis;
			if (normalAxis < 0 || normalAxis >=
					static_cast<std::int32_t>(a_mirror.worldHalfExtents.size()) ||
				!ReadCameraNearPlaneSEH(a_sourceCamera, a_cameraNearPlane)) {
				return false;
			}
			a_normalHalfThickness =
				a_mirror.worldHalfExtents[static_cast<std::size_t>(normalAxis)];
			if (MirrorFleetPolicy::paneAlignedCamera.load(std::memory_order_relaxed)) {
				auto plane = ToMirrorMathPlane(a_mirror.plane.plane);
				if (!PlanarMirrorMath::NormalizePlane(plane) ||
					!MirrorCameraOverride::SelectPaneAlignedNearPlane(
						PlanarMirrorMath::SignedDistance(plane, a_sourcePose.origin),
						a_normalHalfThickness, a_cameraNearPlane,
						MirrorCameraOverride::kDefaultClipBias, a_cameraNearPlane)) return false;
			}
			return PlanarMirrorMath::EvaluateMirrorCaptureClearance(
				ToMirrorMathPlane(a_mirror.plane.plane), a_sourcePose.origin,
				a_normalHalfThickness,
				a_cameraNearPlane, MirrorCameraOverride::kDefaultClipBias,
				a_clearance,
				g_mirrorNativeNearClearanceEnabled.load(std::memory_order_acquire) ?
					PlanarMirrorMath::MirrorCaptureClearancePolicy::
						kNativeNearPlaneOutsideSlab :
					PlanarMirrorMath::MirrorCaptureClearancePolicy::
						kLegacyNearPlaneSlabAndClipBias);
		}

		// Storage grows before the scheduler commits new identities. Allocation
		// failure leaves existing mirrors eligible and their publications intact.
		bool ReconcileMirrorSlots(std::span<const MultiMirrorPolicy::Identity> identities,
			bool handEquipped) noexcept
		{
			static std::vector<MultiMirrorPolicy::Identity> owners;
			const auto needed = (std::max)(g_multiMirrorScheduler.Slots().size(), identities.size());
			AcquireSRWLockExclusive(&g_mirrorAdmissionLock);
			bool complete = false;
			try {
				if (g_mirrorRetainedTargets.size() < needed) g_mirrorRetainedTargets.resize(needed);
				if (g_mirrorRetainedGenerations.size() < needed) g_mirrorRetainedGenerations.resize(needed);
				if (g_multiMirrorAdmissionGates.size() < needed) g_multiMirrorAdmissionGates.resize(needed);
				if (owners.size() < needed) owners.resize(needed);
				if (g_multiMirrorScheduler.Reconcile(identities, handEquipped)) {
					const auto& slots = g_multiMirrorScheduler.Slots();
					for (std::size_t i = 0; i < owners.size(); ++i) {
						const auto owner = i < slots.size() ? slots[i] : MultiMirrorPolicy::Identity{};
						if (owners[i] != owner) {
							MirrorFramePublication::InvalidateSlot(i, "slot-owner-changed");
							g_multiMirrorAdmissionGates[i].Reset();
							// Retire GPU storage when a reference leaves the admitted set.
							// The shared staging target never belongs to a retained slot.
							auto* target = g_mirrorRetainedTargets[i];
							if (!owner.Valid() && target && target != g_mirrorTarget && !target->Bound()) {
								if (g_mirrorPublishedTarget == target) {
									g_mirrorPublishedTarget = nullptr;
									g_mirrorPublishedTargetGeneration = 0;
								}
								target->Release();
								g_mirrorRetainedGenerations[i] = 0;
							}
							owners[i] = owner;
						}
					}
					complete = true;
					if (MirrorCaptureWorkPolicy::enabled.load(std::memory_order_relaxed) &&
						slots.empty() && g_mirrorTarget && !g_mirrorTarget->Bound() &&
						g_activeTarget == nullptr && !g_pendingExactMirrorCapture.valid &&
						MirrorFramePublication::CaptureResourcesDisjoint(
							g_mirrorTarget->ColorResourceIdentity(), g_mirrorTarget->DepthResourceIdentity())) {
						if (g_mirrorPublishedTarget == g_mirrorTarget) {
							g_mirrorPublishedTarget = nullptr;
							g_mirrorPublishedTargetGeneration = 0;
						}
						g_mirrorTarget->Release();
						g_mirrorTargetGeneration = 0;
					}
				}
			} catch (...) {
			}
			ReleaseSRWLockExclusive(&g_mirrorAdmissionLock);
			return complete;
		}

		void ResetMirrorCaptureAdmission(bool activeOnly = false) noexcept
		{
			AcquireSRWLockExclusive(&g_mirrorAdmissionLock);
			if (activeOnly && MirrorFramePublication::MultiMirrorEnabled() &&
				g_activeMirrorSlot < g_multiMirrorAdmissionGates.size()) {
				g_multiMirrorAdmissionGates[g_activeMirrorSlot].Reset();
				ReleaseSRWLockExclusive(&g_mirrorAdmissionLock);
				return;
			}
			g_mirrorAdmissionGate.Reset();
			for (auto& gate : g_multiMirrorAdmissionGates)
				gate.Reset();
			ReleaseSRWLockExclusive(&g_mirrorAdmissionLock);
		}

		[[nodiscard]] bool EvaluateStableMirrorAdmission(
			const MirrorRecognition::ActiveMirror& a_mirror,
			const MirrorInteriorEligibility::CellIdentity& a_retainedInterior,
			const PlanarMirrorMath::MirrorCaptureClearance& a_clearance,
			float a_normalHalfThickness,
			MirrorCaptureAdmission::Result& a_result,
			float& a_playerPlaneDistance,
			float& a_bodyNearestPlaneDistance,
			float& a_requiredPlayerDistance,
			float& a_bodyBoundRadius,
			bool a_revalidate = false) noexcept
		{
			a_result = {};
			a_playerPlaneDistance = 0.0f;
			a_bodyNearestPlaneDistance = 0.0f;
			a_requiredPlayerDistance = 0.0f;
			a_bodyBoundRadius = 0.0f;
			MirrorPlayerInclusion::BodyBoundsSnapshot bodySnapshot{};
			auto normalizedPlane = ToMirrorMathPlane(a_mirror.plane.plane);
			if (!MirrorPlayerInclusion::TrySnapshotBodyBounds(bodySnapshot) ||
				!PlanarMirrorMath::NormalizePlane(normalizedPlane) ||
				!std::isfinite(a_normalHalfThickness) ||
				a_normalHalfThickness < 0.0f) {
				ResetMirrorCaptureAdmission(MirrorFramePublication::MultiMirrorEnabled());
				return false;
			}

			a_playerPlaneDistance =
				PlanarMirrorMath::SignedDistance(
					normalizedPlane, bodySnapshot.playerPosition);
			a_bodyBoundRadius = bodySnapshot.boundRadius;
			a_bodyNearestPlaneDistance =
				PlanarMirrorMath::SignedDistance(
					normalizedPlane, bodySnapshot.boundCenter) - a_bodyBoundRadius;
			a_requiredPlayerDistance =
				a_normalHalfThickness + MirrorCameraOverride::kDefaultClipBias;

			// Aperture-limited body gate: the clearance exists to keep the body
			// out of the oblique near-clip band IN FRONT OF THE PANE, but the
			// signed-distance test measures against the infinite plane, so
			// standing beside the mirror starved captures into long stale
			// periods (2026-08-07 owner report: stale image + partial-white
			// wedges). When the body bound is laterally outside the pane's
			// conservative circumradius, the sample reports the body as clear;
			// the telemetry out-parameters keep the true values.
			float samplePlayerPlaneDistance = a_playerPlaneDistance;
			float sampleBodyNearestPlaneDistance = a_bodyNearestPlaneDistance;
			{
				const auto& paneCenter = a_mirror.plane.center;
				const DirectX::XMFLOAT3 toBody{
					bodySnapshot.boundCenter.x - paneCenter.x,
					bodySnapshot.boundCenter.y - paneCenter.y,
					bodySnapshot.boundCenter.z - paneCenter.z };
				const float normalComponent =
					normalizedPlane.normal.x * toBody.x +
					normalizedPlane.normal.y * toBody.y +
					normalizedPlane.normal.z * toBody.z;
				const float lateralSquared =
					toBody.x * toBody.x + toBody.y * toBody.y +
					toBody.z * toBody.z - normalComponent * normalComponent;
				float largest = 0.0f;
				float second = 0.0f;
				for (const float extent : a_mirror.worldHalfExtents) {
					if (!std::isfinite(extent))
						continue;
					if (extent >= largest) {
						second = largest;
						largest = extent;
					} else if (extent > second) {
						second = extent;
					}
				}
				const float apertureRadius = std::sqrt(
					largest * largest + second * second) + a_bodyBoundRadius;
				if (std::isfinite(lateralSquared) &&
					lateralSquared > apertureRadius * apertureRadius) {
					const float clearedDistance =
						a_requiredPlayerDistance + 1.0f;
					if (samplePlayerPlaneDistance < clearedDistance)
						samplePlayerPlaneDistance = clearedDistance;
					if (sampleBodyNearestPlaneDistance < clearedDistance)
						sampleBodyNearestPlaneDistance = clearedDistance;
				}
			}
			const auto nowMilliseconds =
				std::chrono::duration_cast<std::chrono::milliseconds>(
					std::chrono::steady_clock::now().time_since_epoch()).count();
			// Outdoors there is no attached interior cell, so the retained identity
			// is empty and Identity::Valid() would reject every sample as invalid
			// input — the reason exterior mirrors still stayed white after the
			// interior gate itself was removed (549 kInvalidInput rejects). Fall
			// back to the mirror's own parent cell, which is populated in both
			// interiors and exteriors and is exactly as stable an identity.
			const auto& admissionCell =
				(a_retainedInterior.address != 0 && a_retainedInterior.formID != 0) ?
				a_retainedInterior : a_mirror.parentCell;
			const MirrorCaptureAdmission::Sample sample{
				.identity = {
					.formID = a_mirror.formID,
					.generation = a_mirror.candidateGeneration,
					.cellAddress = admissionCell.address,
					.cellFormID = admissionCell.formID,
					.bodyRootAddress = bodySnapshot.rootAddress },
				.sequence = MirrorFleetPolicy::enabled.load(std::memory_order_relaxed) ?
					MirrorFleetRuntime::AdmissionSequence({ a_mirror.formID, a_mirror.candidateGeneration },
						g_mainWorldInvocationSourceSequence) : g_counters.driverCalls.load(std::memory_order_relaxed),
				.nowMilliseconds = nowMilliseconds,
				.facingCosine = a_mirror.plane.facingCosine,
				.sourcePlaneDistance = a_clearance.sourcePlaneDistance,
				.requiredSourceDistance = a_clearance.requiredDistance,
				.playerPlaneDistance = samplePlayerPlaneDistance,
				.bodyNearestPlaneDistance = sampleBodyNearestPlaneDistance,
				.requiredPlayerDistance = a_requiredPlayerDistance
			};
			AcquireSRWLockExclusive(&g_mirrorAdmissionLock);
			auto& admissionGate = MirrorFramePublication::MultiMirrorEnabled() &&
				g_activeMirrorSlot < g_multiMirrorAdmissionGates.size() ?
				g_multiMirrorAdmissionGates[g_activeMirrorSlot] : g_mirrorAdmissionGate;
			auto admissionPolicy = kMirrorAdmissionPolicy;
			if (MirrorFramePublication::MultiMirrorEnabled()) {
				const auto cadence = g_multiMirrorEveryFrameEnabled.load(std::memory_order_relaxed) ?
					std::size_t{ 1 } : g_multiMirrorScheduler.Slots().size() + 1;
				admissionPolicy.maximumSequenceGap = cadence;
				const auto maximum = (std::numeric_limits<std::int64_t>::max)();
				admissionPolicy.maximumSampleGapMilliseconds = cadence > static_cast<std::uint64_t>(
					maximum / admissionPolicy.maximumSampleGapMilliseconds) ? maximum :
					admissionPolicy.maximumSampleGapMilliseconds * static_cast<std::int64_t>(cadence);
			}
			if (MirrorFleetPolicy::enabled.load(std::memory_order_relaxed))
				admissionPolicy = MirrorFleetPolicy::AdmissionPolicy();
			a_result = a_revalidate ?
				admissionGate.Revalidate(sample, admissionPolicy) :
				admissionGate.Evaluate(sample, admissionPolicy);
			ReleaseSRWLockExclusive(&g_mirrorAdmissionLock);
			return a_result.rejection !=
			       MirrorCaptureAdmission::Rejection::kInvalidInput;
		}

		[[nodiscard]] const char* MirrorAdmissionRejectionName(
			MirrorCaptureAdmission::Rejection a_rejection) noexcept
		{
			switch (a_rejection) {
			case MirrorCaptureAdmission::Rejection::kFacing:
				return "edge-on";
			case MirrorCaptureAdmission::Rejection::kSourceClearance:
				return "source-clearance";
			case MirrorCaptureAdmission::Rejection::kPlayerClearance:
				return "player-clearance";
			case MirrorCaptureAdmission::Rejection::kStabilizing:
				return "stabilizing";
			case MirrorCaptureAdmission::Rejection::kInvalidInput:
				return "invalid-input";
			case MirrorCaptureAdmission::Rejection::kNone:
			default:
				return "accepted";
			}
		}

		[[nodiscard]] bool TryGetSceneAndContext(
			RE::NiAVObject*& sceneRoot,
			ID3D11DeviceContext*& context) noexcept
		{
			__try {
				sceneRoot = static_cast<RE::NiAVObject*>(RE::Main::WorldRootNode());
				context = Context();
				return true;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				sceneRoot = nullptr;
				context = nullptr;
				return false;
			}
		}

		[[nodiscard]] bool EndRenderTargetSEH(
			RenderTarget* a_target,
			ID3D11DeviceContext* context) noexcept
		{
			__try {
				if (!a_target)
					return true;
				(void)a_target->End(context);
				// A sticky target restore fault remains terminal even if a later D3D
				// readback happens to observe the OM unbound.
				return a_target->RestorationSucceeded();
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				g_counters.targetRestoreFailures.fetch_add(1, std::memory_order_relaxed);
				return false;
			}
		}

		[[nodiscard]] bool BeginRenderTargetSEH(
			RenderTarget* a_target,
			ID3D11DeviceContext* context,
			const float clearColor[4]) noexcept
		{
			bool result = false;
			__try {
				result = a_target && a_target->Begin(context, clearColor);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				result = false;
			}
			if (result)
				return true;

			g_counters.targetBeginFailures.fetch_add(1, std::memory_order_relaxed);
			if (!a_target)
				return false;
			if (a_target->LastBeginRejectedOutputMergerUAV())
				g_counters.targetOutputUAVSkips.fetch_add(1, std::memory_order_relaxed);

			// Begin marks restoration ownership before its first private OM or
			// viewport mutation.  Therefore even an AV in Rebind/Clear leaves enough
			// state for End to restore the exact entry targets and viewports.  Also
			// call End when ownership was not acquired so an incomplete read-only
			// snapshot is discarded rather than retained by the fault-latched target.
			const bool restoreWasPending = a_target->Bound();
			if (!EndRenderTargetSEH(a_target, context)) {
				g_counters.targetBeginRollbackFailures.fetch_add(1, std::memory_order_relaxed);
				LogBeginRollbackFailureNoexcept(
					g_lastException.load(std::memory_order_relaxed));
				return false;
			}
			if (restoreWasPending)
				g_counters.targetBeginRollbacks.fetch_add(1, std::memory_order_relaxed);
			return false;
		}

		[[nodiscard]] bool ReleaseRenderTargetSEH(
			RenderTarget* a_target,
			ID3D11DeviceContext* context) noexcept
		{
			__try {
				if (a_target)
					a_target->Release(context);
				return true;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
		}

