		[[nodiscard]] bool SameCapturePlane(
			const PlanarMirrorMath::Plane& a_left,
			const PlanarMirrorMath::Plane& a_right) noexcept
		{
			constexpr float tolerance = 1.0e-4f;
			return std::abs(a_left.normal.x - a_right.normal.x) <= tolerance &&
			       std::abs(a_left.normal.y - a_right.normal.y) <= tolerance &&
			       std::abs(a_left.normal.z - a_right.normal.z) <= tolerance &&
			       std::abs(a_left.distance - a_right.distance) <= tolerance;
		}

		void RevokeMismatchedMirrorFrame(
			const MirrorRecognition::ActiveMirror& a_activeMirror) noexcept
		{
			MirrorFramePublication::Snapshot snapshot{};
			if (MirrorFramePublication::TryGetSnapshot(snapshot) &&
				(snapshot.candidateFormID != a_activeMirror.formID ||
					snapshot.candidateGeneration != a_activeMirror.candidateGeneration ||
					!SameCapturePlane(
						snapshot.capturePlane,
						ToMirrorMathPlane(a_activeMirror.plane.plane)))) {
				InvalidateMirrorFrame();
			}
		}

		

		

		

