		void WriteCameraPose(
			RE::NiTransform& a_transform,
			const MirrorCameraOverride::CameraPose& a_pose) noexcept
		{
			a_transform.translate = { a_pose.origin.x, a_pose.origin.y, a_pose.origin.z };
			auto& rotation = a_transform.rotate;
			rotation.entry[0][0] = a_pose.forward.x;
			rotation.entry[1][0] = a_pose.forward.y;
			rotation.entry[2][0] = a_pose.forward.z;
			rotation.entry[0][1] = a_pose.up.x;
			rotation.entry[1][1] = a_pose.up.y;
			rotation.entry[2][1] = a_pose.up.z;
			rotation.entry[0][2] = a_pose.right.x;
			rotation.entry[1][2] = a_pose.right.y;
			rotation.entry[2][2] = a_pose.right.z;
		}

		/**
		 * The hand capture camera is written as a standalone NiCamera whose world
		 * pose must be exactly the level pose the hand path intends.  Uploads are
		 * validated only against the camera's own world transform, so a parent node
		 * or an engine rewrite between configuration and upload would render every
		 * hand capture (player and room together) rolled while all upload checks
		 * still pass.  Reject the capture instead: a level portrait camera always has
		 * a horizontal right axis and an upward up axis.
		 */
		[[nodiscard]] __declspec(noinline) bool HandCameraPoseLevelAndStandalone(
			const RE::NiCamera* a_camera) noexcept
		{
			if (!a_camera)
				return false;
			constexpr float kAxisTolerance = 2.0e-3F;
			bool standalone = false;
			MirrorCameraOverride::CameraPose pose{};
			__try {
				standalone = a_camera->parent == nullptr;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
			if (!standalone ||
				!MirrorCameraOverride::ReadFlatCameraPose(a_camera, pose))
				return false;
			const auto finite3 = [](const DirectX::XMFLOAT3& value) noexcept {
				return std::isfinite(value.x) && std::isfinite(value.y) &&
					std::isfinite(value.z);
			};
			const auto unit = [](const DirectX::XMFLOAT3& value) noexcept {
				return std::abs(
					value.x * value.x + value.y * value.y + value.z * value.z -
					1.0F) <= 3.0F * kAxisTolerance;
			};
			return finite3(pose.forward) && finite3(pose.up) &&
				finite3(pose.right) && unit(pose.forward) && unit(pose.up) &&
				unit(pose.right) && std::abs(pose.right.z) <= kAxisTolerance &&
				pose.up.z > 0.0F;
		}

		

		

		

		/*
		 * ---- VR 1.4.15 mono private capture (Task E) ---------------------------
		 * The VR engine renders both eyes in one instanced pass driven by (a) the
		 * shadow state's two ViewData/posAdjust eye slots and (b) the NiCamera's
		 * per-eye frustum/position/rotation arrays. Every private capture renders
		 * one mono image using only its constructor-owned camera entries. Both
		 * shadow-state eyes are made identical and restored around each pass.
		 * These helpers are no-ops on flat runtimes.
		 */
		struct VRMonoPassScope
		{
			std::array<std::byte,
				2 * static_cast<std::size_t>(kVRShadowStateCameraDataStride)> cameraData{};
			std::array<std::byte,
				2 * static_cast<std::size_t>(kVRShadowStatePosAdjustStride)> posAdjust{};
			VRMirrorCameraPolicy::StereoLease stereo{};
			bool eyeSlotsArmed{ false };
		};
		// Render-thread owned: armed once per private pass by ExecuteNativePass,
		// disarmed by RestoreRendererState (the callers' existing cleanup path).
		VRMonoPassScope g_vrMonoPassScope{};
		// Set around private descriptor culls so a fault there is attributed to the
		// mono-normalized camera (log-only counter, no behaviour change).
		bool g_vrMonoDescriptorCullActive{ false };

		[[nodiscard]] inline bool VRMonoRuntime() noexcept
		{
			static const bool vr = ExactVRRuntime();
			return vr;
		}

		[[nodiscard]] inline std::byte* VRShadowStateBytes() noexcept
		{
			auto* shadowState = RE::BSGraphics::RendererShadowState::GetSingleton();
			return shadowState ? reinterpret_cast<std::byte*>(shadowState) : nullptr;
		}

		[[nodiscard]] bool VerifyVRStereoLayoutSEH() noexcept
		{
			if (!VRMonoRuntime())
				return false;
			// Exact native cube-map save/zero/restore sites all address the same
			// selector. The on-disk Steam image is packed; check live .text here.
			constexpr std::array<std::uint8_t, 7> save{ 0x0F, 0xB6, 0x05, 0x58, 0xCA, 0xE3, 0x01 };
			constexpr std::array<std::uint8_t, 7> zero{ 0xC6, 0x05, 0x4E, 0xCA, 0xE3, 0x01, 0x00 };
			constexpr std::array<std::uint8_t, 6> restore{ 0x88, 0x05, 0x8A, 0xC6, 0xE3, 0x01 };
			__try {
				const auto base = REL::Module::get().base();
				return reinterpret_cast<std::uintptr_t>(VRShadowStateBytes()) == base + 0x3180DB0 &&
					std::memcmp(reinterpret_cast<const void*>(base + 0x1344CA9), save.data(), save.size()) == 0 &&
					std::memcmp(reinterpret_cast<const void*>(base + 0x1344CB3), zero.data(), zero.size()) == 0 &&
					std::memcmp(reinterpret_cast<const void*>(base + 0x1345078), restore.data(), restore.size()) == 0;
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				return false;
			}
		}

		// Native CAA7F0 owns frustum/position/rotation arrays sized by viewCount.
		// DD1320 consumes positions and 3x3 world rotations, never 4x4 matrices.
		[[nodiscard]] bool NormalizeVRCameraToMonoRaw(
			RE::NiCamera* a_camera, bool& a_changed) noexcept
		{
			a_changed = false;
			auto& vr = a_camera->GetVRRuntimeData();
			if (!vr.eyeFrustums.data() || !vr.eyePositions.data() || !vr.eyeRotations.data() ||
				vr.eyeFrustums.size() > vr.eyeFrustums.capacity() ||
				vr.eyePositions.size() > vr.eyePositions.capacity() ||
				vr.eyeRotations.size() > vr.eyeRotations.capacity())
				return false;
			return VRMirrorCameraPolicy::Normalize(vr.viewCount,
				std::span{ vr.eyeFrustums.data(), vr.eyeFrustums.size() },
				std::span{ vr.eyePositions.data(), vr.eyePositions.size() },
				std::span{ vr.eyeRotations.data(), vr.eyeRotations.size() },
				a_camera->GetRuntimeData2().viewFrustum,
				a_camera->world.translate, a_camera->world.rotate, a_changed);
		}

		bool NormalizeVRCameraToMonoSEH(RE::NiCamera* a_camera, bool a_reapply) noexcept
		{
			if (!VRMonoRuntime())
				return true;
			if (!a_camera)
				return false;
			bool changed = false;
			bool complete = false;
			bool faulted = false;
			__try {
				complete = NormalizeVRCameraToMonoRaw(a_camera, changed);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				faulted = true;
			}
			if (faulted) {
				g_counters.vrMonoCameraFaults.fetch_add(1, std::memory_order_relaxed);
				LatchFault(__LINE__);
				return false;
			}
			g_counters.vrMonoCameraNormalizations.fetch_add(1, std::memory_order_relaxed);
			if (!complete) {
				g_counters.vrMonoCameraArraySkips.fetch_add(1, std::memory_order_relaxed);
				LatchFault(__LINE__);
			}
			if (a_reapply && changed)
				g_counters.vrMonoCameraReapplyChanges.fetch_add(1, std::memory_order_relaxed);
			return complete;
		}

		// E2: shadow-state eye 1 = eye 0 (cameraData + 0x250, posAdjust + 0xC).
		[[nodiscard]] bool MirrorVRShadowStateEyeSlotsRaw(bool& a_changed) noexcept
		{
			a_changed = false;
			auto* bytes = VRShadowStateBytes();
			if (!bytes)
				return false;
			if (g_vrMonoPassScope.stereo.Armed() && !g_vrMonoPassScope.stereo.Prepare(
				{ bytes, VRMirrorCameraPolicy::kStereoStateExtent }))
				return false;
			const auto& layout = SelectedShadowStateLayout();
			std::byte* camera0 = bytes + layout.cameraData;
			std::byte* camera1 = camera0 + kVRShadowStateCameraDataStride;
			if (std::memcmp(camera1, camera0, kVRShadowStateCameraDataStride) != 0) {
				std::memcpy(camera1, camera0, kVRShadowStateCameraDataStride);
				a_changed = true;
			}
			std::byte* pos0 = bytes + layout.posAdjust;
			std::byte* pos1 = pos0 + kVRShadowStatePosAdjustStride;
			if (std::memcmp(pos1, pos0, kVRShadowStatePosAdjustStride) != 0) {
				std::memcpy(pos1, pos0, kVRShadowStatePosAdjustStride);
				a_changed = true;
			}
			return true;
		}

		// Runs at every private-pass SetDirtyStates commit (the only in-file hook
		// between the wrapper's SetCameraData and the draws).  The "changes"
		// counter tells whether E1 already left both engine-written eyes equal.
		[[nodiscard]] bool MirrorVRShadowStateEyeSlotsSEH() noexcept
		{
			if (!VRMonoRuntime())
				return true;
			bool changed = false;
			bool ok = false;
			__try {
				ok = MirrorVRShadowStateEyeSlotsRaw(changed);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				ok = false;
			}
			if (!ok) {
				g_counters.vrMonoEyeSlotMirrorFaults.fetch_add(1, std::memory_order_relaxed);
				return false;
			}
			g_counters.vrMonoEyeSlotMirrors.fetch_add(1, std::memory_order_relaxed);
			if (changed)
				g_counters.vrMonoEyeSlotMirrorChanges.fetch_add(1, std::memory_order_relaxed);
			return true;
		}

		[[nodiscard]] bool BeginVRMonoPassScopeRaw(VRMonoPassScope& a_scope) noexcept
		{
			auto* bytes = VRShadowStateBytes();
			if (!bytes)
				return false;
			const auto& layout = SelectedShadowStateLayout();
			std::memcpy(
				a_scope.cameraData.data(), bytes + layout.cameraData,
				a_scope.cameraData.size());
			std::memcpy(
				a_scope.posAdjust.data(), bytes + layout.posAdjust,
				a_scope.posAdjust.size());
			a_scope.eyeSlotsArmed = true;
			g_counters.vrMonoEyeSlotSnapshots.fetch_add(1, std::memory_order_relaxed);
			if (g_vrDrawStereo0Enabled.load(std::memory_order_acquire)) {
				if (!a_scope.stereo.Begin({ bytes, VRMirrorCameraPolicy::kStereoStateExtent }))
					return false;
				g_counters.vrDrawStereoOverrides.fetch_add(1, std::memory_order_relaxed);
			} else if (HandMirrorApprovedContentReadOnlyObserver::VRSceneFixEnabled()) {
				return false;  // Requested correction lacks its exact native layout proof.
			}
			return true;
		}

		// E2/E5: snapshot BOTH eye slots (and arm the drawStereo experiment) once
		// per private pass.  Refuses to overwrite an outer snapshot: an unbalanced
		// scope means the cleanup path never ran, and the pass is rejected.
		[[nodiscard]] bool BeginVRMonoPassScopeSEH() noexcept
		{
			if (!VRMonoRuntime())
				return true;
			auto& scope = g_vrMonoPassScope;
			if (scope.eyeSlotsArmed || scope.stereo.Armed()) {
				g_counters.vrMonoEyeSlotSnapshotRejects.fetch_add(
					1, std::memory_order_relaxed);
				return false;
			}
			bool ok = false;
			__try {
				ok = BeginVRMonoPassScopeRaw(scope);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				ok = false;
			}
			if (!ok) {
				g_counters.vrMonoEyeSlotSnapshotRejects.fetch_add(
					1, std::memory_order_relaxed);
			}
			return ok;
		}

		[[nodiscard]] bool RestoreVRDrawStereoRaw(VRMonoPassScope& a_scope) noexcept
		{
			auto* bytes = VRShadowStateBytes();
			if (!bytes)
				return false;
			return a_scope.stereo.Restore({ bytes, VRMirrorCameraPolicy::kStereoStateExtent });
		}

		// Cleanup order inside RestoreRendererState: drawStereo first (the engine's
		// SetCameraData restore must never observe the experiment), then the engine
		// restore, then the exact pre-pass eye slots.
		[[nodiscard]] bool RestoreVRDrawStereoSEH() noexcept
		{
			auto& scope = g_vrMonoPassScope;
			if (!scope.stereo.Armed())
				return true;
			bool ok = false;
			__try {
				ok = RestoreVRDrawStereoRaw(scope);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				ok = false;
			}
			(ok ? g_counters.vrDrawStereoRestores :
				g_counters.vrDrawStereoRestoreFailures).fetch_add(
				1, std::memory_order_relaxed);
			return ok;
		}

		[[nodiscard]] bool RestoreVRShadowStateEyeSlotsRaw(
			const VRMonoPassScope& a_scope,
			bool& a_rewritten) noexcept
		{
			a_rewritten = false;
			auto* bytes = VRShadowStateBytes();
			if (!bytes)
				return false;
			const auto& layout = SelectedShadowStateLayout();
			std::byte* camera = bytes + layout.cameraData;
			std::byte* pos = bytes + layout.posAdjust;
			if (std::memcmp(camera, a_scope.cameraData.data(), a_scope.cameraData.size()) != 0) {
				std::memcpy(camera, a_scope.cameraData.data(), a_scope.cameraData.size());
				a_rewritten = true;
			}
			if (std::memcmp(pos, a_scope.posAdjust.data(), a_scope.posAdjust.size()) != 0) {
				std::memcpy(pos, a_scope.posAdjust.data(), a_scope.posAdjust.size());
				a_rewritten = true;
			}
			return std::memcmp(camera, a_scope.cameraData.data(), a_scope.cameraData.size()) == 0 &&
			       std::memcmp(pos, a_scope.posAdjust.data(), a_scope.posAdjust.size()) == 0;
		}

		// Restores BOTH eye slots from the pre-pass snapshot.  "rewrites" counts
		// passes where the engine's own SetCameraData restore had left different
		// bytes (i.e. the snapshot was not the main view the engine re-derived).
		[[nodiscard]] bool RestoreVRShadowStateEyeSlotsSEH() noexcept
		{
			auto& scope = g_vrMonoPassScope;
			if (!scope.eyeSlotsArmed)
				return true;
			bool rewritten = false;
			bool ok = false;
			__try {
				ok = RestoreVRShadowStateEyeSlotsRaw(scope, rewritten);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				ok = false;
			}
			if (ok) {
				scope.eyeSlotsArmed = false;
				g_counters.vrMonoEyeSlotRestores.fetch_add(1, std::memory_order_relaxed);
				if (rewritten) {
					g_counters.vrMonoEyeSlotRestoreRewrites.fetch_add(
						1, std::memory_order_relaxed);
				}
			} else {
				g_counters.vrMonoEyeSlotRestoreFailures.fetch_add(
					1, std::memory_order_relaxed);
			}
			return ok;
		}

		

		[[nodiscard]] bool ConfigureCamera(
			RE::NiCamera* a_source,
			RE::NiCamera* a_destination,
			const PlanarMirrorMath::Plane* a_reflectionPlane,
			const MirrorCameraOverride::CameraPose* a_sourcePose) noexcept
		{
			if (!a_source || !a_destination || a_source == a_destination)
				return false;

			__try {
				a_destination->GetRuntimeData2() = a_source->GetRuntimeData2();
				a_destination->local = a_source->world;

				if (a_reflectionPlane) {
					MirrorCameraOverride::CameraPose fallbackSourcePose{};
					const auto* sourcePose = a_sourcePose;
					if (!sourcePose) {
						if (!MirrorCameraOverride::ReadFlatCameraPose(
								a_source, fallbackSourcePose))
							return false;
						sourcePose = &fallbackSourcePose;
					}
					MirrorCameraOverride::CameraPose reflectedPose{};
					if (!MirrorCameraOverride::BuildReflectedCameraPose(
							*sourcePose, *a_reflectionPlane, reflectedPose))
						return false;
					WriteCameraPose(a_destination->local, reflectedPose);
				} else {
					const RE::NiPoint3 right = a_source->world.rotate.GetVectorZ();
					DirectX::XMFLOAT3 offsetPosition{};
					if (!SecondViewMath::OffsetSideways(
							{ a_source->world.translate.x, a_source->world.translate.y,
								a_source->world.translate.z },
							{ right.x, right.y, right.z },
							kSidewaysOffsetUnits,
							offsetPosition))
						return false;

					a_destination->local.translate = {
						offsetPosition.x, offsetPosition.y, offsetPosition.z };
				}
				RE::NiUpdateData updateData{};
				a_destination->UpdateWorldData(&updateData);
				a_destination->UpdateWorldBound();
				if (!NormalizeVRCameraToMonoSEH(a_destination, false))
					return false;
				return true;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
		}

		[[nodiscard]] bool AlignWorldMirrorCamera(
			RE::NiCamera* camera, const MirrorCameraOverride::CameraPose& source,
			const PlanarMirrorMath::Plane& plane, const PlanarMirrorMath::PaneFit& pane,
			float nearPlane) noexcept
		{
			MirrorCameraOverride::CameraPose aligned{};
			if (!camera || !std::isfinite(nearPlane) || nearPlane <= 0 ||
				!MirrorCameraOverride::BuildPaneAlignedReflectedCameraPose(source, plane, pane, aligned))
				return false;
			__try {
				auto& frustum = camera->GetRuntimeData2().viewFrustum;
				if (!std::isfinite(frustum.fNear) || frustum.fNear <= 0 || nearPlane >= frustum.fFar) return false;
				const float scale = nearPlane / frustum.fNear;
				frustum.fLeft *= scale; frustum.fRight *= scale;
				frustum.fTop *= scale; frustum.fBottom *= scale;
				frustum.fNear = nearPlane;
				WriteCameraPose(camera->local, aligned);
				RE::NiUpdateData update{};
				camera->UpdateWorldData(&update);
				camera->UpdateWorldBound();
				return NormalizeVRCameraToMonoSEH(camera, false);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
		}

		
		static_assert(std::is_trivially_copyable_v<RE::NiCamera::RUNTIME_DATA2>);
		static_assert(sizeof(RE::NiCamera::RUNTIME_DATA2) == 0x38);

		

		

		

		

		

		

		

		[[nodiscard]] bool ConfigurePlanarCameraFromFrozenFrustum(
			RE::NiCamera* destination,
			const PlanarMirrorMath::Plane& reflectionPlane,
			const MirrorPaneDelivery::FrozenSourceCamera& source,
			const MirrorCameraOverride::RasterPerspectiveFrustum&
				rasterFrustum) noexcept
		{
			if (!destination || !source.valid || source.cameraIdentity == 0 ||
				!rasterFrustum.valid) {
				return false;
			}
			static_assert(sizeof(RE::NiCamera::RUNTIME_DATA2) == 0x38);
			__try {
				RE::NiCamera::RUNTIME_DATA2 frozenRuntime{};
				std::memcpy(
					&frozenRuntime, source.runtimeData2.data(),
					source.runtimeData2.size());
				// Pair the private capture with the exact M5 raster sample that owns
				// its publication metadata.  Runtime metadata is frozen at the same
				// observation; the perspective frustum is reconstructed from the
				// authoritative raster projection rather than a later live NiCamera.
				frozenRuntime.viewFrustum.fLeft = rasterFrustum.left;
				frozenRuntime.viewFrustum.fRight = rasterFrustum.right;
				frozenRuntime.viewFrustum.fTop = rasterFrustum.top;
				frozenRuntime.viewFrustum.fBottom = rasterFrustum.bottom;
				frozenRuntime.viewFrustum.fNear = rasterFrustum.nearPlane;
				frozenRuntime.viewFrustum.fFar = rasterFrustum.farPlane;
				frozenRuntime.viewFrustum.bOrtho = false;
				destination->GetRuntimeData2() = frozenRuntime;

				const MirrorCameraOverride::CameraPose sourcePose{
					.origin = source.origin,
					.forward = source.forward,
					.up = source.up,
					.right = source.right
				};
				MirrorCameraOverride::CameraPose reflectedPose{};
				PlanarMirrorMath::Plane normalizedPlane = reflectionPlane;
				if (!PlanarMirrorMath::NormalizePlane(normalizedPlane) ||
					!MirrorCameraOverride::BuildReflectedCameraPose(
						sourcePose, normalizedPlane, reflectedPose)) {
					return false;
				}
				destination->local.scale = 1.0F;
				WriteCameraPose(destination->local, reflectedPose);
				RE::NiUpdateData updateData{};
				destination->UpdateWorldData(&updateData);
				destination->UpdateWorldBound();
				if (!NormalizeVRCameraToMonoSEH(destination, false))
					return false;
				return true;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
		}

		[[nodiscard]] bool ConfigurePlanarCameraFromFrozenRaster(
			RE::NiCamera* destination,
			const PlanarMirrorMath::Plane& reflectionPlane,
			const MirrorPaneDelivery::FrozenSourceCamera& source) noexcept
		{
			return source.rasterAuthoritative &&
				ConfigurePlanarCameraFromFrozenFrustum(
					destination, reflectionPlane, source, source.rasterFrustum);
		}

		[[nodiscard]] bool ConfigureHandPlanarCameraFromFrozenRaster(
			RE::NiCamera* destination,
			const PlanarMirrorMath::Plane& reflectionPlane,
			const MirrorPaneDelivery::FrozenSourceCamera& source) noexcept
		{
			return source.rasterAuthoritative &&
				source.unjitteredRasterAuthoritative &&
				ConfigurePlanarCameraFromFrozenFrustum(
					destination, reflectionPlane, source,
					source.rasterFrustumUnjittered);
		}

		/**
		 * Portrait zoom body framing (HandMirrorPortraitZoomPolicy).  Input:
		 * the player's foot height and the slider blend; output: the widened
		 * frustum factor applied and the sampling-window anchor to use.
		 */
		struct HandPortraitBodyFramingRequest
		{
			float bodyBottomZ{ 0.0F };
			float blend{ 0.0F };
			float portraitZoom{ HandMirrorSettings::kDefaultPortraitZoom };
			DirectX::XMFLOAT3 samplingAnchor{};
			float appliedFrustumWiden{ 1.0F };
		};

		[[nodiscard]] __declspec(noinline) bool TryReadWorldRootCameraPoseSEH(
			DirectX::XMFLOAT3& origin, DirectX::XMFLOAT3& forward) noexcept
		{
			__try {
				RE::NiCamera* camera = nullptr;
				if (!TryGetWorldRootCamera(camera) || !camera)
					return false;
				origin = { camera->world.translate.x, camera->world.translate.y,
					camera->world.translate.z };
				forward = { camera->world.rotate.entry[0][0],
					camera->world.rotate.entry[1][0],
					camera->world.rotate.entry[2][0] };
				return true;
			} __except (EXCEPTION_EXECUTE_HANDLER) {
				return false;
			}
		}

		[[nodiscard]] __declspec(noinline) bool TryReadHandBodyBottomSEH(
			RE::NiAVObject* bodyRoot, float& output) noexcept
		{
			__try {
				if (!bodyRoot)
					return false;
				output = bodyRoot->world.translate.z;
				return std::isfinite(output);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
		}

		[[nodiscard]] bool ConfigureHandCameraFromFrozenRaster(
			RE::NiCamera* destination,
			const PlanarMirrorMath::Plane& reflectionPlane,
			const MirrorPaneDelivery::FrozenSourceCamera& source,
			const DirectX::XMFLOAT3& retainedFaceAnchor,
			DirectX::XMFLOAT4X4& outputProjection,
			const HandPortraitPhysicalClipEvidence* physicalClipEvidence = nullptr,
			HandPortraitBodyFramingRequest* bodyFraming = nullptr)
			noexcept
		{
			outputProjection = {};
			if (!destination || !source.valid || source.cameraIdentity == 0 ||
				!source.rasterAuthoritative ||
				!source.unjitteredRasterAuthoritative ||
				!source.rasterFrustumUnjittered.valid ||
				!std::isfinite(retainedFaceAnchor.x) ||
				!std::isfinite(retainedFaceAnchor.y) ||
				!std::isfinite(retainedFaceAnchor.z))
				return false;
			static_assert(sizeof(RE::NiCamera::RUNTIME_DATA2) == 0x38);
			__try {
				RE::NiCamera::RUNTIME_DATA2 frozenRuntime{};
				std::memcpy(
					&frozenRuntime, source.runtimeData2.data(),
					source.runtimeData2.size());
				MirrorCameraOverride::CameraPose sourcePose{
					.origin = source.origin,
					.forward = source.forward,
					.up = source.up,
					.right = source.right
				};
				MirrorCameraOverride::CameraPose reflectedPose{};
				PlanarMirrorMath::Plane normalizedPlane = reflectionPlane;
				if (!PlanarMirrorMath::NormalizePlane(normalizedPlane))
					return false;
				if (!MirrorCameraOverride::BuildReflectedCameraPose(
						sourcePose, normalizedPlane, reflectedPose)) {
					return false;
				}
				// Move the capture eye halfway toward the handheld pane so the final
				// projective mapping frames roughly twice as much of the player as V31.
				// This accepted distance scale is independent of the deferred pitch
				// theorem. Keep the renderer camera normal-aligned and at the proven
				// face height for the conventional near-plane contract.
				const float reflectedPaneDistance = -PlanarMirrorMath::SignedDistance(
					normalizedPlane, reflectedPose.origin);
				if (!std::isfinite(reflectedPaneDistance) ||
					reflectedPaneDistance <= 1.0e-4F) {
					return false;
				}
				const float extraDistance = reflectedPaneDistance *
					(HandMirrorPortraitPitchPolicy::kReflectedPaneDistanceScale - 1.0F);
				reflectedPose.origin.x -= normalizedPlane.normal.x * extraDistance;
				reflectedPose.origin.y -= normalizedPlane.normal.y * extraDistance;
				reflectedPose.origin.z -= normalizedPlane.normal.z * extraDistance;

				using namespace DirectX;
				const XMVECTOR oldForward = XMLoadFloat3(&reflectedPose.forward);
				const XMVECTOR oldUp = XMLoadFloat3(&reflectedPose.up);
				const XMVECTOR oldRight = XMLoadFloat3(&reflectedPose.right);
				const float handedness = XMVectorGetX(
					XMVector3Dot(XMVector3Cross(oldForward, oldUp), oldRight));
				if (!std::isfinite(handedness) || std::abs(handedness) <= 1.0e-4F)
					return false;
				const XMVECTOR aimedForward = XMLoadFloat3(&normalizedPlane.normal);
				const XMVECTOR worldUp = XMVectorSet(0.0F, 0.0F, 1.0F, 0.0F);
				XMVECTOR aimedUp = XMVectorSubtract(
					worldUp, XMVectorScale(
						aimedForward,
						XMVectorGetX(XMVector3Dot(worldUp, aimedForward))));
				const float aimedUpLength = XMVectorGetX(XMVector3Length(aimedUp));
				if (!std::isfinite(aimedUpLength) || aimedUpLength <= 1.0e-6F)
					return false;
				aimedUp = XMVectorScale(aimedUp, 1.0F / aimedUpLength);
				XMVECTOR aimedRight = XMVector3Normalize(
					XMVector3Cross(aimedForward, aimedUp));
				if (handedness < 0.0F)
					aimedRight = XMVectorNegate(aimedRight);
				if (handedness >= 0.0F)
					aimedUp = XMVector3Normalize(
						XMVector3Cross(aimedRight, aimedForward));
				else
					aimedUp = XMVector3Normalize(
						XMVector3Cross(aimedForward, aimedRight));
				XMStoreFloat3(&reflectedPose.forward, aimedForward);
				XMStoreFloat3(&reflectedPose.up, aimedUp);
				XMStoreFloat3(&reflectedPose.right, aimedRight);

				const float cameraPlaneSignedDistance =
					PlanarMirrorMath::SignedDistance(
						normalizedPlane, reflectedPose.origin);
				const float cameraForwardPlaneDot =
					reflectedPose.forward.x * normalizedPlane.normal.x +
					reflectedPose.forward.y * normalizedPlane.normal.y +
					reflectedPose.forward.z * normalizedPlane.normal.z;
				// Use the current retained face/eye anchor. This validates one current
				// point, not the complete skinned bounds checked by the physical clip
				// evidence; source.origin can still differ after the retained tuple reread.
				const float retainedAnchorDepth =
					(retainedFaceAnchor.x - reflectedPose.origin.x) *
						reflectedPose.forward.x +
					(retainedFaceAnchor.y - reflectedPose.origin.y) *
						reflectedPose.forward.y +
					(retainedFaceAnchor.z - reflectedPose.origin.z) *
						reflectedPose.forward.z;
				auto clip = HandMirrorPortraitClipPolicy::Build({
					.sourceLeft = source.rasterFrustumUnjittered.left,
					.sourceRight = source.rasterFrustumUnjittered.right,
					.sourceTop = source.rasterFrustumUnjittered.top,
					.sourceBottom = source.rasterFrustumUnjittered.bottom,
					.sourceNear = source.rasterFrustumUnjittered.nearPlane,
					.sourceFar = source.rasterFrustumUnjittered.farPlane,
					.sourceProjection33 = source.rasterProjectionUnjittered._33,
					.sourceProjection43 = source.rasterProjectionUnjittered._43,
					.sourceProjection34 = source.rasterProjectionUnjittered._34,
					.sourceProjection44 = source.rasterProjectionUnjittered._44,
					.cameraPlaneSignedDistance = cameraPlaneSignedDistance,
					.cameraForwardPlaneDot = cameraForwardPlaneDot,
					.retainedAnchorDepth = retainedAnchorDepth
				});
				if (!clip)
					return false;

				// The portrait pose is deliberately stable, but clipping still belongs to
				// the real mirror.  Tighten the conventional near plane only from the
				// hidden third-person pane which shares the captured body's world/animation
				// epoch. A conservative retained head/helmet bound limits the advance before
				// it can slice the face or equipped horns. If the complete physical depth is
				// unsafe, the policy still takes the proven-safe partial advance; invalid
				// evidence keeps the already-valid virtual near without rejecting capture.
				if (physicalClipEvidence && physicalClipEvidence->valid) {
					if (!physicalClipEvidence->retainedBounds.valid ||
						physicalClipEvidence->selectedGraphicsFrame !=
							physicalClipEvidence->retainedBounds.selectedGraphicsFrame) {
						g_handPortraitPhysicalClipBoundsUnavailable.fetch_add(
							1, std::memory_order_relaxed);
					} else {
						const auto selection = ObserveHandPortraitPhysicalPaneAxialDepth(
							physicalClipEvidence->pane, reflectedPose, clip.nearPlane,
							physicalClipEvidence->retainedBounds, clip.farPlane);
						if (selection.valid && selection.applied) {
							const float selectedNear = selection.selectedNearDepth;
							const float denominator = clip.farPlane - selectedNear;
							const float frustumScale = selectedNear /
								source.rasterFrustumUnjittered.nearPlane;
							clip.left =
								source.rasterFrustumUnjittered.left * frustumScale;
							clip.right =
								source.rasterFrustumUnjittered.right * frustumScale;
							clip.top = source.rasterFrustumUnjittered.top * frustumScale;
							clip.bottom =
								source.rasterFrustumUnjittered.bottom * frustumScale;
							clip.nearPlane = selectedNear;
							clip.frustumScale = frustumScale;
							clip.projection33 = clip.farPlane / denominator;
							clip.projection43 =
								-selectedNear * clip.farPlane / denominator;
						}
					}
				}

				// Below default zoom, fit the body before sampling. The old crop-only
				// downward shift was clamped at the texture edge and cut off the legs.
				// The opt-in correction also moves the capture eye parallel to its
				// plane: direction and all axial near/far/physical-clip depths survive.
				float frustumWiden = 1.0F;
				if (bodyFraming) {
					const HandMirrorPortraitZoomPolicy::BodyFramingInput framingInput{
							.faceAnchorZ = retainedFaceAnchor.z,
							.bodyBottomZ = bodyFraming->bodyBottomZ,
							.anchorDepth = retainedAnchorDepth,
							.sourceTopSlope = source.rasterFrustumUnjittered.top /
								source.rasterFrustumUnjittered.nearPlane,
							.blend = bodyFraming->blend
						};
					auto framing = g_handBodyFramingEnabled.load(std::memory_order_relaxed) ?
						HandMirrorPortraitZoomPolicy::ComputeCenteredBodyFraming(framingInput,
							reflectedPose.forward.z, reflectedPose.up.z,
							HandMirrorSettings::kMinimumPortraitZoom) :
						HandMirrorPortraitZoomPolicy::ComputeBodyFraming(framingInput);
					// A steep view can put a body endpoint behind this camera. Retain
					// legacy framing in that case instead of losing a working capture.
					if (!framing.valid)
						framing = HandMirrorPortraitZoomPolicy::ComputeBodyFraming(framingInput);
					if (!framing.valid)
						return false;
					reflectedPose.origin.x -= reflectedPose.up.x * framing.captureDropUnits;
					reflectedPose.origin.y -= reflectedPose.up.y * framing.captureDropUnits;
					reflectedPose.origin.z -= reflectedPose.up.z * framing.captureDropUnits;
					frustumWiden = framing.frustumWiden;
					clip.left *= frustumWiden;
					clip.right *= frustumWiden;
					clip.top *= frustumWiden;
					clip.bottom *= frustumWiden;
					bodyFraming->samplingAnchor = retainedFaceAnchor;
					bodyFraming->samplingAnchor.z -= framing.anchorDropUnits;
					bodyFraming->appliedFrustumWiden = frustumWiden;
				}

				// Keep the source FOV while moving the conventional NiCamera near plane
				// onto the exact virtual portrait plane. SetCameraData therefore emits
				// near/far constants that match the frozen standard projection consumed
				// by every UpdateCameraData upload and by SoftEffect depth reconstruction.
				frozenRuntime.viewFrustum.fLeft = clip.left;
				frozenRuntime.viewFrustum.fRight = clip.right;
				frozenRuntime.viewFrustum.fTop = clip.top;
				frozenRuntime.viewFrustum.fBottom = clip.bottom;
				frozenRuntime.viewFrustum.fNear = clip.nearPlane;
				frozenRuntime.viewFrustum.fFar = clip.farPlane;
				frozenRuntime.viewFrustum.bOrtho = false;
				DirectX::XMFLOAT4X4 adjustedProjection =
					source.rasterProjectionUnjittered;
				adjustedProjection._33 = clip.projection33;
				adjustedProjection._43 = clip.projection43;
				adjustedProjection._11 /= frustumWiden;
				adjustedProjection._22 /= frustumWiden;
				const float* projectionValues = &adjustedProjection._11;
				for (std::size_t index = 0; index < 16; ++index) {
					if (!std::isfinite(projectionValues[index]))
						return false;
				}

				destination->GetRuntimeData2() = frozenRuntime;
				destination->local.scale = 1.0F;
				WriteCameraPose(destination->local, reflectedPose);
				RE::NiUpdateData updateData{};
				destination->UpdateWorldData(&updateData);
				destination->UpdateWorldBound();
				if (!NormalizeVRCameraToMonoSEH(destination, false))
					return false;
				const auto& appliedFrustum =
					destination->GetRuntimeData2().viewFrustum;
				if (appliedFrustum.bOrtho ||
					!HandMirrorPortraitClipPolicy::NearlyEqual(
						appliedFrustum.fLeft, clip.left) ||
					!HandMirrorPortraitClipPolicy::NearlyEqual(
						appliedFrustum.fRight, clip.right) ||
					!HandMirrorPortraitClipPolicy::NearlyEqual(
						appliedFrustum.fTop, clip.top) ||
					!HandMirrorPortraitClipPolicy::NearlyEqual(
						appliedFrustum.fBottom, clip.bottom) ||
					!HandMirrorPortraitClipPolicy::NearlyEqual(
						appliedFrustum.fNear, clip.nearPlane) ||
					!HandMirrorPortraitClipPolicy::NearlyEqual(
						appliedFrustum.fFar, clip.farPlane)) {
					return false;
				}
				outputProjection = adjustedProjection;
				return true;
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				return false;
			}
		}

		// The live NiCamera node can be a frame out of step with the camera
		// snapshot this frame actually renders with (game thread runs ahead), so
		// a capture posed from it disagrees with the delivery's mainView by about
		// one frame of motion — the owner-measured moving ghosting
		// (staleOrigin on 33% of moving frames, unchanged by TAA state). When
		// the frame-pose marker is armed, the reflected pose derives from the
		// renderer shadow state's own frame snapshot instead: origin from
		// posAdjust, basis from ViewData's explicit viewForward/viewUp/viewRight.
		static_assert(offsetof(
			RE::BSGraphics::RendererShadowState::FLAT_RUNTIME_DATA,
			posAdjust) == 0x35C);
		static_assert(offsetof(
			RE::BSGraphics::RendererShadowState::FLAT_RUNTIME_DATA,
			cameraData) == 0x380);
		// VR 1.4.15 keeps per-eye arrays; eye 0 (left) is read (ShadowStateLayout).
		static_assert(offsetof(
			RE::BSGraphics::RendererShadowState::VR_RUNTIME_DATA,
			posAdjust) == 0x3A4);
		static_assert(offsetof(
			RE::BSGraphics::RendererShadowState::VR_RUNTIME_DATA,
			cameraData) == 0x3E0);
		static_assert(offsetof(RE::BSGraphics::ViewData, viewUp) == 0x00);
		static_assert(offsetof(RE::BSGraphics::ViewData, viewRight) == 0x10);
		static_assert(offsetof(RE::BSGraphics::ViewData, viewForward) == 0x20);

		[[nodiscard]] bool TryReadRenderFramePoseSEH(
			MirrorCameraOverride::CameraPose& a_pose) noexcept
		{
			bool read = false;
			__try {
				auto* shadowState =
					RE::BSGraphics::RendererShadowState::GetSingleton();
				if (shadowState) {
					const auto* bytes = reinterpret_cast<const std::byte*>(
						&shadowState->GetRuntimeData());
					const auto& shadowLayout = SelectedShadowStateLayout();
					DirectX::XMFLOAT3 origin{};
					DirectX::XMFLOAT3 up{};
					DirectX::XMFLOAT3 rightAxis{};
					DirectX::XMFLOAT3 forward{};
					std::memcpy(&origin, bytes + shadowLayout.posAdjust, sizeof(origin));
					std::memcpy(&up, bytes + shadowLayout.cameraData + 0x00, sizeof(up));
					std::memcpy(&rightAxis, bytes + shadowLayout.cameraData + 0x10, sizeof(rightAxis));
					std::memcpy(&forward, bytes + shadowLayout.cameraData + 0x20, sizeof(forward));
					const auto finite3 = [](const DirectX::XMFLOAT3& v) noexcept {
						return std::isfinite(v.x) && std::isfinite(v.y) &&
							std::isfinite(v.z);
					};
					const auto dot3 = [](const DirectX::XMFLOAT3& a,
						const DirectX::XMFLOAT3& b) noexcept {
						return a.x * b.x + a.y * b.y + a.z * b.z;
					};
					if (finite3(origin) && finite3(up) && finite3(rightAxis) &&
						finite3(forward)) {
						const float forwardLength = dot3(forward, forward);
						const float upLength = dot3(up, up);
						const float rightLength = dot3(rightAxis, rightAxis);
						constexpr float kUnitTolerance = 1.0e-2f;
						constexpr float kOrthoTolerance = 1.0e-2f;
						if (std::abs(forwardLength - 1.0f) <= kUnitTolerance &&
							std::abs(upLength - 1.0f) <= kUnitTolerance &&
							std::abs(rightLength - 1.0f) <= kUnitTolerance &&
							std::abs(dot3(forward, up)) <= kOrthoTolerance &&
							std::abs(dot3(forward, rightAxis)) <= kOrthoTolerance &&
							std::abs(dot3(up, rightAxis)) <= kOrthoTolerance) {
							a_pose.origin = origin;
							a_pose.forward = forward;
							a_pose.up = up;
							a_pose.right = rightAxis;
							read = true;
						}
					}
				}
			} __except (RecordDiagnosticException(GetExceptionCode())) {
				read = false;
			}
			return read;
		}

		// Ghidra (2026-08-18): the fence call site SE 0x5B1B47 IS
		// BSGraphics::State::SetCameraData and the chained finalizer 0x5B1B4C is
		// DrawWorld::MainAccum. The frame's definitive main-view camera is
		// therefore in the shadow state exactly when our fence hook's chain
		// returns — and polluted by sub-pass cameras (shadow cascades at
		// ~46,000 units in the falsified live-read experiment) by the time the
		// replay runs after MainAccum. Snapshot at the chain, consume at the
		// replay: same render thread, same frame.
		struct FramePoseSnapshot
		{
			MirrorCameraOverride::CameraPose pose{};
			bool valid{ false };
		};
		FramePoseSnapshot g_framePoseSnapshot{};

		// The frame's raster main view, read at the fence immediately after the
		// engine's SetCameraData (the one moment the +0xB0 viewProjection and
		// posAdjust provably belong to this frame's main view — the same offsets
		// the M5 delivery reads successfully during draws). Published with each
		// capture so the pane can draw a self-consistent pair (owner-approved
		// "one frame late but consistent" design, 2026-08-18).
		struct FrameMainViewSnapshot
		{
			DirectX::XMFLOAT4X4 viewProjection{};
			DirectX::XMFLOAT3 origin{};
			bool valid{ false };
		};
		FrameMainViewSnapshot g_frameMainViewSnapshot{};

		void CaptureFrameMainViewSnapshotNoexcept() noexcept
		{
			bool read = false;
			__try {
				auto* shadowState =
					RE::BSGraphics::RendererShadowState::GetSingleton();
				if (shadowState) {
					const auto* bytes = reinterpret_cast<const std::byte*>(
						&shadowState->GetRuntimeData());
					const auto& shadowLayout = SelectedShadowStateLayout();
					DirectX::XMFLOAT3 origin{};
					DirectX::XMFLOAT4X4 viewProjection{};
					std::memcpy(&origin, bytes + shadowLayout.posAdjust, sizeof(origin));
					std::memcpy(
						&viewProjection, bytes + shadowLayout.cameraData + 0xB0,
						sizeof(viewProjection));
					if (std::isfinite(origin.x) && std::isfinite(origin.y) &&
						std::isfinite(origin.z)) {
						g_frameMainViewSnapshot.viewProjection = viewProjection;
						g_frameMainViewSnapshot.origin = origin;
						read = true;
					}
				}
			} __except (RecordDiagnosticException(GetExceptionCode())) {
				read = false;
			}
			g_frameMainViewSnapshot.valid = read;
		}

		void CaptureFramePoseSnapshotNoexcept() noexcept
		{
			// Captured every frame regardless of the consumption marker so the
			// snapshot-vs-NiCamera mapping can be measured passively; the raw
			// field interpretation was falsified twice (2026-08-18: live read
			// grabbed sub-pass cameras; fence read still mismatched by up to 32
			// units with a visually wrong basis), so consumption stays disabled
			// until the logged dot-matrix identifies the actual convention.
			MirrorCameraOverride::CameraPose pose{};
			if (TryReadRenderFramePoseSEH(pose)) {
				g_framePoseSnapshot.pose = pose;
				g_framePoseSnapshot.valid = true;
			} else {
				g_framePoseSnapshot.valid = false;
			}
		}

		void LogFramePoseComparisonNoexcept(
			const MirrorCameraOverride::CameraPose& a_cameraPose) noexcept
		{
			// One line roughly every 512 reflected attempts (~8 seconds at 60fps).
			if ((g_counters.reflectedAttempts.load(std::memory_order_relaxed) &
					0x1FF) != 1)
				return;
			if (!g_framePoseSnapshot.valid) {
				try {
					logger::info("[RR][M3][frame-pose-map] snapshot invalid");
				} catch (...) {
				}
				return;
			}
			const auto& snap = g_framePoseSnapshot.pose;
			const auto dot3 = [](const DirectX::XMFLOAT3& a,
				const DirectX::XMFLOAT3& b) noexcept {
				return a.x * b.x + a.y * b.y + a.z * b.z;
			};
			try {
				logger::info(
					"[RR][M3][frame-pose-map] originDelta=({:.3f},{:.3f},{:.3f}) "
					"snapF.(camF/camU/camR)=({:.4f},{:.4f},{:.4f}) "
					"snapU.(camF/camU/camR)=({:.4f},{:.4f},{:.4f}) "
					"snapR.(camF/camU/camR)=({:.4f},{:.4f},{:.4f})",
					snap.origin.x - a_cameraPose.origin.x,
					snap.origin.y - a_cameraPose.origin.y,
					snap.origin.z - a_cameraPose.origin.z,
					dot3(snap.forward, a_cameraPose.forward),
					dot3(snap.forward, a_cameraPose.up),
					dot3(snap.forward, a_cameraPose.right),
					dot3(snap.up, a_cameraPose.forward),
					dot3(snap.up, a_cameraPose.up),
					dot3(snap.up, a_cameraPose.right),
					dot3(snap.right, a_cameraPose.forward),
					dot3(snap.right, a_cameraPose.up),
					dot3(snap.right, a_cameraPose.right));
			} catch (...) {
			}
		}

		// The copied source frustum swings with the player's view while the
		// pane-fitted projection stays anchored to the mirror, so pane-edge
		// content (off-axis NPCs, geometry behind the player) was frustum-culled
		// out of the private pass while still displayable (2026-08-18 owner run).
		// Every private cull — borrowed lists, player root, supplemental actors —
		// reads this one NiFrustum, so widening it here covers all of them.
		// Over-inclusion is discarded by the pane projection and oblique clip.
		// Owner, 2026-09-17 ("cull more tightly to what the pane can actually
		// show"): a standing mirror renders through the pane-fitted projection
		// alone, so its cull can be exactly the pane's slopes with the same margin
		// -- nothing outside them can reach its image. `a_fit` replaces the copied
		// frustum instead of widening it; the hand mirror keeps the union because
		// its projection is expanded to include the source view.
		[[nodiscard]] bool WidenPrivateCullFrustumForPaneSEH(
			RE::NiCamera* a_camera,
			const PlanarMirrorMath::PaneFit& a_paneFit,
			float a_marginScale,
			bool a_fit = false) noexcept
		{
			if (!a_camera || !std::isfinite(a_marginScale) ||
				a_marginScale < 1.0f)
				return false;
			bool widened = false;
			__try {
				const auto& rotate = a_camera->world.rotate;
				const DirectX::XMFLOAT3 eye{
					a_camera->world.translate.x, a_camera->world.translate.y,
					a_camera->world.translate.z };
				const DirectX::XMFLOAT3 forward{
					rotate.entry[0][0], rotate.entry[1][0], rotate.entry[2][0] };
				const DirectX::XMFLOAT3 upAxis{
					rotate.entry[0][1], rotate.entry[1][1], rotate.entry[2][1] };
				const DirectX::XMFLOAT3 rightAxis{
					rotate.entry[0][2], rotate.entry[1][2], rotate.entry[2][2] };
				PlanarMirrorMath::PaneCullSlopes slopes{};
				if (PlanarMirrorMath::BuildPaneCullSlopes(
						a_paneFit, eye, forward, upAxis, rightAxis,
						a_marginScale, slopes)) {
					auto& frustum = a_camera->GetRuntimeData2().viewFrustum;
					const float nearPlane = frustum.fNear;
					if (std::isfinite(nearPlane) && nearPlane > 0.0f &&
						!frustum.bOrtho) {
						const float left = a_fit ? slopes.minRight * nearPlane :
							std::min(frustum.fLeft, slopes.minRight * nearPlane);
						const float rightEdge = a_fit ? slopes.maxRight * nearPlane :
							std::max(frustum.fRight, slopes.maxRight * nearPlane);
						const float top = a_fit ? slopes.maxUp * nearPlane :
							std::max(frustum.fTop, slopes.maxUp * nearPlane);
						const float bottom = a_fit ? slopes.minUp * nearPlane :
							std::min(frustum.fBottom, slopes.minUp * nearPlane);
						if (std::isfinite(left) && std::isfinite(rightEdge) &&
							std::isfinite(top) && std::isfinite(bottom) &&
							left < rightEdge && bottom < top) {
							frustum.fLeft = left;
							frustum.fRight = rightEdge;
							frustum.fTop = top;
							frustum.fBottom = bottom;
							widened = true;
							// The widened NiFrustum must reach both VR eye frustums.
							if (!NormalizeVRCameraToMonoSEH(a_camera, true))
								return false;
						}
					}
				}
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				widened = false;
			}
			return widened;
		}

		// Pixels per unit of view-space slope for this capture, from the pane's
		// own slopes without margin: the projection spreads the same pixels over
		// a slightly wider interval, so this errs toward keeping objects.
		[[nodiscard]] RE::BSShaderAccumulator* GetCurrentAccumulatorRaw()
		{
			using Getter = RE::BSShaderAccumulator*();
			static REL::Relocation<Getter> getter{ RELOCATION_ID(98997, 105651) };
			return getter();
		}

		[[nodiscard]] RE::NiCamera* GetCurrentCameraRaw()
		{
			static REL::Relocation<RE::NiCamera**> currentCamera{
				REL::VariantID(527667, 414580, 0x3422FD8) };
			return *currentCamera.get();
		}

