		[[nodiscard]] bool RestoreRendererState(
			RE::NiCamera* a_savedCamera,
			RE::BSShaderAccumulator* a_savedAccumulator,
			RE::NiCamera* a_cameraDataRestoreSource = nullptr,
			std::uint32_t* a_failureMask = nullptr) noexcept
		{
			// These are independent engine-owned states.  A fault while restoring one
			// must not prevent attempts to restore the remaining exact entry values.
			RE::NiCamera* cameraDataRestoreSource = a_cameraDataRestoreSource;
			if (!cameraDataRestoreSource &&
				!TryGetWorldRootCamera(cameraDataRestoreSource)) {
				cameraDataRestoreSource = nullptr;
			}
			// VR mono capture (Task E5/E2): end the drawStereo experiment before the
			// engine restore; re-impose the exact pre-pass eye slots after it.
			const bool vrDrawStereoRestored = RestoreVRDrawStereoSEH();
			const bool cameraDataRestored = RestoreMainCameraDataSEH(
				cameraDataRestoreSource);
			const bool vrEyeSlotsRestored = RestoreVRShadowStateEyeSlotsSEH();
			const bool cameraWriteSucceeded = RestoreCurrentCameraSEH(a_savedCamera);
			const bool accumulatorWriteSucceeded =
				RestoreCurrentAccumulatorSEH(a_savedAccumulator);

			RE::NiCamera* observedCamera = nullptr;
			RE::BSShaderAccumulator* observedAccumulator = nullptr;
			const bool cameraVerified = TryGetCurrentCamera(observedCamera) &&
				observedCamera == a_savedCamera;
			const bool accumulatorVerified = TryGetCurrentAccumulator(observedAccumulator) &&
				observedAccumulator == a_savedAccumulator;
			bool exactHandSourceVerified = true;
			if (a_cameraDataRestoreSource) {
				RE::NiCamera* worldRootCamera = nullptr;
				exactHandSourceVerified =
					TryGetWorldRootCamera(worldRootCamera) &&
					worldRootCamera == a_cameraDataRestoreSource;
				if (!exactHandSourceVerified) {
					g_counters.handCameraCohortPostRestoreRejects.fetch_add(
						1, std::memory_order_relaxed);
				}
			}
			std::uint32_t failureMask = 0;
			if (!cameraDataRestored)
				failureMask |= 1u << 0;
			if (!cameraWriteSucceeded)
				failureMask |= 1u << 1;
			if (!accumulatorWriteSucceeded)
				failureMask |= 1u << 2;
			if (!cameraVerified)
				failureMask |= 1u << 3;
			if (!accumulatorVerified)
				failureMask |= 1u << 4;
			if (!exactHandSourceVerified)
				failureMask |= 1u << 5;
			if (!vrDrawStereoRestored)
				failureMask |= 1u << 6;
			if (!vrEyeSlotsRestored)
				failureMask |= 1u << 7;
			if (a_failureMask)
				*a_failureMask |= failureMask;
			return cameraDataRestored && cameraWriteSucceeded &&
			       accumulatorWriteSucceeded && cameraVerified &&
			       accumulatorVerified && exactHandSourceVerified &&
			       vrDrawStereoRestored && vrEyeSlotsRestored;
		}

