		[[nodiscard]] bool FinitePlane(const RE::NiPlane& a_plane) noexcept
		{
			return std::isfinite(a_plane.normal.x) && std::isfinite(a_plane.normal.y) &&
			       std::isfinite(a_plane.normal.z) && std::isfinite(a_plane.constant);
		}

		[[nodiscard]] bool BuildMirrorCullPlanes(
			RE::NiCamera* a_camera,
			const PlanarMirrorMath::Plane& a_mirrorPlane,
			RE::NiFrustumPlanes& a_output)
		{
			using BuildWorldFrustumPlanes = void(
				RE::NiFrustumPlanes*, const RE::NiFrustum*, const RE::NiTransform*);
			static REL::Relocation<BuildWorldFrustumPlanes> buildWorldFrustumPlanes{
				REL::VariantID(69431, 70808, 0xCB2780) };

			if (!a_camera)
				return false;
			PlanarMirrorMath::Plane normalizedPlane = a_mirrorPlane;
			if (!PlanarMirrorMath::NormalizePlane(normalizedPlane))
				return false;

			a_output = {};
			buildWorldFrustumPlanes(
				&a_output, &a_camera->GetRuntimeData2().viewFrustum, &a_camera->world);
			a_output.activePlanes.set(
				RE::NiFrustumPlanes::ActivePlane::kNear,
				RE::NiFrustumPlanes::ActivePlane::kFar,
				RE::NiFrustumPlanes::ActivePlane::kLeft,
				RE::NiFrustumPlanes::ActivePlane::kRight,
				RE::NiFrustumPlanes::ActivePlane::kTop,
				RE::NiFrustumPlanes::ActivePlane::kBottom);
			a_output.basePlaneStates = 0x3F;
			a_output.cullingPlanes[RE::NiFrustumPlanes::Planes::kNear].normal = {
				normalizedPlane.normal.x,
				normalizedPlane.normal.y,
				normalizedPlane.normal.z
			};
			a_output.cullingPlanes[RE::NiFrustumPlanes::Planes::kNear].constant =
				normalizedPlane.distance + MirrorCameraOverride::kDefaultClipBias;

			for (const auto& plane : a_output.cullingPlanes) {
				if (!FinitePlane(plane))
					return false;
			}
			return a_output.activePlanes.underlying() == 0x3F &&
			       a_output.basePlaneStates == 0x3F;
		}

		[[nodiscard]] bool PreflightHandPhysicalFragmentClip(
			RE::NiCamera* a_camera,
			HandPortraitPhysicalClipEvidence& a_evidence) noexcept
		{
			a_evidence.physicalFragmentClipPreflightAccepted = false;
			a_evidence.preparedWorldCullPlane = {};
			a_evidence.preparedWorldCullPlanes = {};
			g_handPhysicalFragmentClipAdmissionAttempts.fetch_add(
				1, std::memory_order_relaxed);
			g_handPortraitPhysicalWorldCullAttempts.fetch_add(
				1, std::memory_order_relaxed);

			const bool exactSE1597 = REL::Module::IsSE() &&
				REL::Module::get().version() == REL::Version{ 1, 5, 97, 0 };
			const bool exactAE161170 = REL::Module::IsAE() &&
				SupportedRuntimePolicy::IsSupportedAEVersion(REL::Module::get().version());
			const bool exactVR1415 = SupportedRuntimePolicy::IsExactVRRuntime();
			if (!a_camera || !a_evidence.valid ||
				!g_handUnifiedCullRuntimeReady.load(std::memory_order_acquire)) {
				g_handPortraitPhysicalWorldCullEvidenceRejects.fetch_add(
					1, std::memory_order_relaxed);
				g_handPhysicalFragmentClipEvidenceRejects.fetch_add(
					1, std::memory_order_relaxed);
				return false;
			}
			if (!BuildHandPortraitPhysicalWorldCullPlane(
					a_evidence, a_evidence.preparedWorldCullPlane)) {
				g_handPortraitPhysicalWorldCullPlaneRejects.fetch_add(
					1, std::memory_order_relaxed);
				g_handPhysicalFragmentClipEvidenceRejects.fetch_add(
					1, std::memory_order_relaxed);
				return false;
			}
			if (!BuildMirrorCullPlanes(
					a_camera, a_evidence.preparedWorldCullPlane,
					a_evidence.preparedWorldCullPlanes)) {
				g_handPortraitPhysicalWorldCullBuildRejects.fetch_add(
					1, std::memory_order_relaxed);
				g_handPhysicalFragmentClipEvidenceRejects.fetch_add(
					1, std::memory_order_relaxed);
				return false;
			}

			const auto& retained = a_evidence.retainedBounds;
			const bool retainedBoundsReady = retained.valid &&
				retained.tupleRevalidatedAfterTraversal &&
				retained.actorRenderRootIdentity != 0 && retained.geometry.valid &&
				retained.geometry.geometryCount != 0 &&
				a_evidence.selectedGraphicsFrame != 0 &&
				a_evidence.selectedGraphicsFrame == retained.selectedGraphicsFrame;
			HandMirrorPhysicalFragmentClipPolicy::PlaneDomain planeDomain{};
			if (retainedBoundsReady) {
				const auto& bounds = retained.geometry;
				planeDomain = HandMirrorPhysicalFragmentClipPolicy::EvaluatePlaneDomain({
					.normalX = a_evidence.preparedWorldCullPlane.normal.x,
					.normalY = a_evidence.preparedWorldCullPlane.normal.y,
					.normalZ = a_evidence.preparedWorldCullPlane.normal.z,
					.distance = a_evidence.preparedWorldCullPlane.distance,
					.cameraX = a_camera->world.translate.x,
					.cameraY = a_camera->world.translate.y,
					.cameraZ = a_camera->world.translate.z,
					.minimumX = bounds.minimumX,
					.minimumY = bounds.minimumY,
					.minimumZ = bounds.minimumZ,
					.maximumX = bounds.maximumX,
					.maximumY = bounds.maximumY,
					.maximumZ = bounds.maximumZ
				});
			}
			const bool conventionalSoftDepthReady =
				!HandMirrorPhysicalClipDepth::Faulted() &&
				HandMirrorPhysicalClipDepth::EnsureDevice(Device());
			const auto route = HandMirrorPhysicalFragmentClipPolicy::SelectRoute({
				.featureEnabled = true,
				.exactSE1597 = exactSE1597,
				.exactAE161170 = exactAE161170 || exactVR1415,
				.raisedPortrait = true,
				.physicalPaneFresh = a_evidence.selectedGraphicsFrame != 0,
				.halfSpaceReady = true,
				.retainedBoundsReady = retainedBoundsReady,
				.cameraBehindPlane = planeDomain.cameraBehindPlane,
				.retainedBoundsReachVisibleHalfSpace =
					planeDomain.retainedBoundsReachVisibleHalfSpace,
				.conventionalSoftDepthReady = conventionalSoftDepthReady
			});
			if (route != HandMirrorPhysicalFragmentClipPolicy::Route::kPhysicalOblique) {
				if (!conventionalSoftDepthReady) {
					g_handPhysicalFragmentClipDepthRejects.fetch_add(
						1, std::memory_order_relaxed);
				} else if (!planeDomain || !planeDomain.cameraBehindPlane ||
					!planeDomain.retainedBoundsReachVisibleHalfSpace) {
					g_handPhysicalFragmentClipDomainRejects.fetch_add(
						1, std::memory_order_relaxed);
				} else {
					g_handPhysicalFragmentClipEvidenceRejects.fetch_add(
						1, std::memory_order_relaxed);
				}
				return false;
			}

			a_evidence.physicalFragmentClipPreflightAccepted = true;
			g_handPhysicalFragmentClipAdmissionAccepts.fetch_add(
				1, std::memory_order_relaxed);
			return true;
		}

		__declspec(noinline) bool PreflightHandPhysicalFragmentClipSEH(
			RE::NiCamera* a_camera,
			HandPortraitPhysicalClipEvidence& a_evidence) noexcept
		{
			bool accepted = false;
			__try {
				accepted = PreflightHandPhysicalFragmentClip(a_camera, a_evidence);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				accepted = false;
			}
			return accepted;
		}

		

		

		

		

		

		

		

		

		

		

		

		

		// SetDirtyStates commits Skyrim's cached raster description before the
		// private pass re-applies its D3D no-cull clone.  Restoring only the D3D
		// object would therefore leave a clean engine cache describing the last
		// private draw.  Preserve the exact flat-runtime cache fields and their
		// two dirty bits alongside the exact D3D state.
		struct FlatRasterShadowSnapshot
		{
			std::uint32_t rasterDirtyBits{ 0 };
			std::uint32_t fillMode{ 0 };
			std::uint32_t cullMode{ 0 };
			std::uint32_t depthBiasMode{ 0 };
			std::uint32_t scissorMode{ 0 };
			bool armed{ false };
		};

		// Raster-state offsets live in ShadowStateLayout (flat 0x98..0xA4, VR
		// 0xA0..0xAC; the dirty flags are +0x00 on both).
		constexpr std::uint32_t kRasterDirtyMask =
			static_cast<std::uint32_t>(RE::BSGraphics::ShaderFlags::DIRTY_RASTER_CULL_MODE) |
			static_cast<std::uint32_t>(RE::BSGraphics::ShaderFlags::DIRTY_RASTER_DEPTH_BIAS);

		static_assert(kRasterDirtyMask == 0x60);
		static_assert(ShadowStateLayout::Flat().stateUpdateFlags == 0x00);
		static_assert(ShadowStateLayout::Flat().rasterStateFillMode == 0x98);
		static_assert(ShadowStateLayout::VR().stateUpdateFlags == 0x00);
		static_assert(ShadowStateLayout::VR().rasterStateFillMode == 0xA0);

		[[nodiscard]] bool CaptureFlatRasterShadowRaw(
			FlatRasterShadowSnapshot* a_snapshot) noexcept
		{
			if (!a_snapshot || a_snapshot->armed || !IsSupportedRuntime())
				return false;
			auto* shadowState = RE::BSGraphics::RendererShadowState::GetSingleton();
			if (!shadowState)
				return false;

			FlatRasterShadowSnapshot captured{};
			auto* bytes = reinterpret_cast<const std::byte*>(shadowState);
			const auto& shadowLayout = SelectedShadowStateLayout();
			std::uint32_t flags = 0;
			std::memcpy(&flags, bytes + shadowLayout.stateUpdateFlags, sizeof(flags));
			std::memcpy(&captured.fillMode, bytes + shadowLayout.rasterStateFillMode, sizeof(captured.fillMode));
			std::memcpy(&captured.cullMode, bytes + shadowLayout.rasterStateCullMode, sizeof(captured.cullMode));
			std::memcpy(
				&captured.depthBiasMode, bytes + shadowLayout.rasterStateDepthBiasMode,
				sizeof(captured.depthBiasMode));
			std::memcpy(
				&captured.scissorMode, bytes + shadowLayout.rasterStateScissorMode,
				sizeof(captured.scissorMode));
			captured.rasterDirtyBits = flags & kRasterDirtyMask;
			captured.armed = true;
			*a_snapshot = captured;
			return true;
		}

		[[nodiscard]] bool RestoreFlatRasterShadowRaw(
			FlatRasterShadowSnapshot* a_snapshot,
			bool a_forceRasterDirty) noexcept
		{
			if (!a_snapshot)
				return false;
			if (!a_snapshot->armed)
				return true;

			auto* shadowState = RE::BSGraphics::RendererShadowState::GetSingleton();
			if (!shadowState) {
				a_snapshot->armed = false;
				return false;
			}
			auto* bytes = reinterpret_cast<std::byte*>(shadowState);
			const auto& shadowLayout = SelectedShadowStateLayout();
			std::uint32_t currentFlags = 0;
			std::memcpy(&currentFlags, bytes + shadowLayout.stateUpdateFlags, sizeof(currentFlags));
			const std::uint32_t expectedDirtyBits = a_forceRasterDirty ?
				kRasterDirtyMask : a_snapshot->rasterDirtyBits;
			const std::uint32_t mergedFlags =
				(currentFlags & ~kRasterDirtyMask) | expectedDirtyBits;

			std::memcpy(bytes + shadowLayout.rasterStateFillMode, &a_snapshot->fillMode, sizeof(a_snapshot->fillMode));
			std::memcpy(bytes + shadowLayout.rasterStateCullMode, &a_snapshot->cullMode, sizeof(a_snapshot->cullMode));
			std::memcpy(
				bytes + shadowLayout.rasterStateDepthBiasMode, &a_snapshot->depthBiasMode,
				sizeof(a_snapshot->depthBiasMode));
			std::memcpy(
				bytes + shadowLayout.rasterStateScissorMode, &a_snapshot->scissorMode,
				sizeof(a_snapshot->scissorMode));
			std::memcpy(bytes + shadowLayout.stateUpdateFlags, &mergedFlags, sizeof(mergedFlags));

			FlatRasterShadowSnapshot restored{};
			std::uint32_t restoredFlags = 0;
			std::memcpy(&restoredFlags, bytes + shadowLayout.stateUpdateFlags, sizeof(restoredFlags));
			std::memcpy(&restored.fillMode, bytes + shadowLayout.rasterStateFillMode, sizeof(restored.fillMode));
			std::memcpy(&restored.cullMode, bytes + shadowLayout.rasterStateCullMode, sizeof(restored.cullMode));
			std::memcpy(
				&restored.depthBiasMode, bytes + shadowLayout.rasterStateDepthBiasMode,
				sizeof(restored.depthBiasMode));
			std::memcpy(
				&restored.scissorMode, bytes + shadowLayout.rasterStateScissorMode,
				sizeof(restored.scissorMode));

			const bool exact = restored.fillMode == a_snapshot->fillMode &&
			                   restored.cullMode == a_snapshot->cullMode &&
			                   restored.depthBiasMode == a_snapshot->depthBiasMode &&
			                   restored.scissorMode == a_snapshot->scissorMode &&
			                   (restoredFlags & kRasterDirtyMask) == expectedDirtyBits;
			a_snapshot->armed = false;
			return exact;
		}

		[[nodiscard]] bool CaptureFlatRasterShadowSEH(
			FlatRasterShadowSnapshot* a_snapshot) noexcept
		{
			bool result = false;
			__try {
				result = CaptureFlatRasterShadowRaw(a_snapshot);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				if (a_snapshot)
					a_snapshot->armed = false;
				result = false;
			}
			if (!result)
				LatchFault(__LINE__);
			return result;
		}

		[[nodiscard]] bool RestoreFlatRasterShadowSEH(
			FlatRasterShadowSnapshot* a_snapshot,
			bool a_forceRasterDirty = false) noexcept
		{
			bool result = false;
			__try {
				result = RestoreFlatRasterShadowRaw(a_snapshot, a_forceRasterDirty);
			} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
				if (a_snapshot)
					a_snapshot->armed = false;
				result = false;
			}
			if (!result)
				LatchFault(__LINE__);
			return result;
		}

