					// are the oriented-bound support widths along the selected
					// tangent/bitangent, exact for any tangent-axis choice.
					mirrorPaneFitReady = PlanarMirrorMath::BuildPaneFit(
						ToMirrorMathSelection(activeMirror.plane),
						activeMirror.worldHalfExtents,
						activeMirror.worldAxes, mirrorPaneFit);
					g_supplementalAnchorFormID.store(
						activeMirror.formID, std::memory_order_release);
