	bool TryGetExactHandSoftDepthBindings(
		ExactHandSoftDepthBindings& output) noexcept
	{
		output = {};
		bool valid = false;
		__try {
			auto* target = g_activeTarget;
			auto* context = Context();
			const bool exactHandTarget = g_activeHandExactMain && target &&
				std::find(
					g_handMirrorTargets.begin(), g_handMirrorTargets.end(), target) !=
					g_handMirrorTargets.end();
			const bool placedTarget = !exactHandTarget && target && g_inSecondView &&
				!g_activeHandExactMain && !g_privateShadowPass &&
				IsInsideMirrorPrimaryCapture() &&
				g_placedSoftDepthEnabled.load(std::memory_order_acquire) &&
				!HandMirrorPhysicalClipDepth::Faulted();
			if ((!exactHandTarget && !placedTarget) || !context || !target->Ready() ||
				!target->Bound()) {
				return false;
			}
			if (placedTarget) {
				MirrorCameraOverride::HandPhysicalDepthProjection projection{};
				if (!MirrorCameraOverride::GetPlacedDepthProjection(nullptr, projection))
					return false;
				const auto resolved = HandMirrorPhysicalClipDepth::Resolve({
					.context = context,
					.colorRTV = target->ColorRTV(),
					.writableDepthDSV = target->DepthDSV(),
					.readOnlyDepthDSV = target->ReadOnlyDepthDSV(),
					.obliqueDepthSRV = target->DepthSRV(),
					.targetIdentity = reinterpret_cast<std::uintptr_t>(target),
					// One Begin per capture cycle; every SoftEffect draw of that
					// cycle reuses the snapshot taken at its first soft draw, after
					// the cycle's opaque groups.
					.depthSnapshotEpoch = projection.generation,
					.width = target->Width(),
					.height = target->Height(),
					.projection = {
						.conventional = projection.conventional,
						.oblique = projection.oblique,
						.generation = projection.generation,
						.valid = projection.valid
					},
					.reducedViewsAllowed = true
				});
				if (!resolved) {
					g_counters.placedSoftDepthUnavailable.fetch_add(1, std::memory_order_relaxed);
					return false;
				}
				output = {
					.context = context,
					.colorRTV = target->ColorRTV(),
					.writableDepthDSV = target->DepthDSV(),
					.readOnlyDepthDSV = target->ReadOnlyDepthDSV(),
					.depthSRV = resolved.conventionalDepthSRV,
					.targetIdentity = reinterpret_cast<std::uintptr_t>(target),
					.width = target->Width(),
					.height = target->Height()
				};
				valid = output.context && output.colorRTV && output.writableDepthDSV &&
					output.readOnlyDepthDSV && output.depthSRV &&
					output.targetIdentity != 0 && output.width != 0 && output.height != 0;
				if (!valid)
					output = {};
				return valid;
			}
			output = {
				.context = context,
				.colorRTV = target->ColorRTV(),
				.writableDepthDSV = target->DepthDSV(),
				.readOnlyDepthDSV = target->ReadOnlyDepthDSV(),
				.depthSRV = target->DepthSRV(),
				.targetIdentity = reinterpret_cast<std::uintptr_t>(target),
				.width = target->Width(),
				.height = target->Height()
			};
			if (g_handPhysicalFragmentClipEnabled.load(
					std::memory_order_acquire) &&
				g_activeHandPortraitCamera) {
				MirrorCameraOverride::HandPhysicalDepthProjection projection{};
				if (!MirrorCameraOverride::GetHandPhysicalDepthProjection(
						g_owner.Camera(), projection)) {
					return false;
				}
				const auto resolved = HandMirrorPhysicalClipDepth::Resolve({
					.context = context,
					.colorRTV = target->ColorRTV(),
					.writableDepthDSV = target->DepthDSV(),
					.readOnlyDepthDSV = target->ReadOnlyDepthDSV(),
					.obliqueDepthSRV = target->DepthSRV(),
					.targetIdentity = reinterpret_cast<std::uintptr_t>(target),
					// One camera generation owns one completed opaque-depth capture.
					// Repeated SoftEffect transactions in that capture reuse this
					// immutable snapshot; exact matrix-bit checks guard reuploads.
					.depthSnapshotEpoch = projection.generation,
					.width = target->Width(),
					.height = target->Height(),
					.projection = {
						.conventional = projection.conventional,
						.oblique = projection.oblique,
						.generation = projection.generation,
						.valid = projection.valid
					}
				});
				if (!resolved)
					return false;
				output.depthSRV = resolved.conventionalDepthSRV;
			}
			valid = output.context && output.colorRTV && output.writableDepthDSV &&
				output.readOnlyDepthDSV && output.depthSRV &&
				output.targetIdentity != 0 && output.width != 0 && output.height != 0;
		} __except (RecordPassException(GetExceptionCode(), GetExceptionInformation(), __LINE__)) {
			valid = false;
		}
		if (!valid)
			output = {};
		return valid;
	}

	void FailStopExactHandSoftDepth() noexcept
	{
		g_counters.handEffectPrivateDepthTransactionFaults.fetch_add(
			1, std::memory_order_relaxed);
		LatchFault(__LINE__);
	}

